"""Minimal ANSI/VT100 screen emulator producing a cell grid."""
import re

class Style:
    __slots__=('fg','bg','bold','underline','reverse','ital','blink','strike')
    def __init__(self):
        self.fg=None; self.bg=None; self.bold=False; self.underline=False
        self.reverse=False; self.ital=False; self.blink=False; self.strike=False
    def copy(self):
        s=Style(); s.__dict__ if False else None
        for a in ('fg','bg','bold','underline','reverse','ital','blink','strike'):
            setattr(s,a,getattr(self,a))
        return s
    def key(self):
        return (self.fg,self.bg,self.bold,self.underline,self.reverse,self.ital,self.blink,self.strike)
    def sgr(self):
        if self.key()==DEF.key(): return ''
        p=[]
        fg,bg=self.fg,self.bg
        attrs=[]
        if self.bold: attrs.append('1')
        if self.underline: attrs.append('4')
        if self.ital: attrs.append('3')
        if self.blink: attrs.append('5')
        if self.reverse: attrs.append('7')
        if self.strike: attrs.append('9')
        if attrs: p.append(';'.join(attrs))
        if fg is not None: p.append(fg)
        if bg is not None: p.append(bg)
        return '\x1b['+ ';'.join(p)+'m'
DEF=Style()

def sgr_reset(s):
    # returns new style after applying a reset
    s.fg=DEF.fg; s.bg=DEF.bg; s.bold=False; s.underline=False; s.reverse=False
    s.ital=False; s.blink=False; s.strike=False
    return s

FG={'30':'30','31':'31','32':'32','33':'33','34':'34','35':'35','36':'36','37':'37',
    '39':'39','90':'90','91':'91','92':'92','93':'93','94':'94','95':'95','96':'96','97':'97'}

def parse_sgr(s, cur):
    i=0
    while i < len(s):
        if s[i]=='0':
            cur=sgr_reset(Style()); i+=1
            continue
        # 38/48 extended
        if s.startswith('38;5;',i):
            j=i+5; k=s.index('m',j) if 'm' in s[j:] else len(s)
            cur.fg='38;5;'+s[j:k].split(';')[0]; i=k; continue
        if s.startswith('38;2;',i):
            j=i+5; parts=s[j:].split(';')[:3]
            cur.fg='38;2;'+';'.join(parts); i=len(s); continue
        if s.startswith('48;5;',i):
            j=i+5; k=s.index('m',j) if 'm' in s[j:] else len(s)
            cur.bg='48;5;'+s[j:k].split(';')[0]; i=k; continue
        if s.startswith('48;2;',i):
            j=i+5; parts=s[j:].split(';')[:3]
            cur.bg='48;2;'+';'.join(parts); i=len(s); continue
        m=re.match(r'(1|2|3|4|5|7|9|21|22|23|24|27|29)', s[i:])
        if m:
            c=m.group(1)
            if c=='1': cur.bold=True
            elif c=='2': cur.bold=False
            elif c=='3': cur.ital=True
            elif c=='4': cur.underline=True
            elif c=='5': cur.blink=True
            elif c=='7': cur.reverse=True
            elif c=='9': cur.strike=True
            elif c=='21': cur.bold=False
            elif c=='22': cur.bold=False
            elif c=='23': cur.ital=False
            elif c=='24': cur.underline=False
            elif c=='27': cur.reverse=False
            elif c=='29': cur.strike=False
            i+=len(c); continue
        m=re.match(r'(3[0-9]|9[0-7]|39)', s[i:])
        if m: cur.fg=m.group(1); i+=2; continue
        m=re.match(r'(4[0-9]|10[0-7]|49)', s[i:])
        if m: cur.bg=m.group(1); i+=len(m.group(1)); continue
        i+=1
    return cur

class Screen:
    def __init__(self, cols=80, rows=24):
        self.cols=cols; self.rows=rows
        self.cells=[[(' ', Style()) for _ in range(cols)] for _ in range(rows)]
        self.cx=0; self.cy=0; self.cur=Style()
    def clear(self):
        self.cells=[[(' ', self.cur.copy()) for _ in range(self.cols)] for _ in range(self.rows)]
    def newline(self):
        self.cy+=1
        if self.cy>=self.rows: self.cy=self.rows-1; self.scroll()
    def scroll(self):
        self.cells.pop(0); self.cells.append([(' ',DEF.copy()) for _ in range(self.cols)])
    def put(self,ch):
        if self.cx>=self.cols:
            self.cx=0; self.newline()
        self.cells[self.cy][self.cx]=(ch,self.cur.copy()); self.cx+=1
    def text(self):
        return '\n'.join(''.join(c[0] for c in row) for row in self.cells)
    def text_nort(self):
        ls=[''.join(c[0] for c in row).rstrip() for row in self.cells]
        return '\n'.join(ls)

def run(data, cols=80, rows=24):
    sc=Screen(cols,rows)
    i=0; n=len(data)
    while i<n:
        c=data[i]
        if c=='\x1b':
            if i+1<n and data[i+1]=='[':
                j=data.find('m',i)
                k=data.find('H',i)
                j2=data.find('J',i); k2=data.find('K',i)
                # find terminator among common finals
                best=None
                for fin in 'mHJKABCDfdrsuGhl':
                    p=data.find(fin,i+2)
                    if p!=-1 and (best is None or p<best[0]): best=(p,fin)
                if best is None: break
                p,fin=best
                body=data[i+2:p]
                i=p+1
                handle_csi(sc,body,fin)
                continue
            elif i+1<n and data[i+1]==']':
                p=data.find('\x07',i)
                q=data.find('\x1b\\',i)
                if p==-1 and q==-1: break
                if p!=-1 and (q==-1 or p<q): i=p+1
                else: i=q+2
                continue
            elif i+1<n and data[i+1]=='(':
                i+=3; continue
            elif i+1<n and data[i+1]=='>':
                i+=2; continue
            elif i+1<n and data[i+1]=='=':
                i+=2; continue
            else:
                i+=2; continue
        if c=='\r': sc.cx=0; i+=1; continue
        if c=='\n': sc.newline(); i+=1; continue
        if c=='\t':
            sc.cx=min(sc.cols-1,(sc.cx//8+1)*8); i+=1; continue
        if c=='\b': sc.cx=max(0,sc.cx-1); i+=1; continue
        sc.put(c); i+=1
    return sc

def handle_csi(sc, body, fin):
    def args(default=1):
        ps=[]
        for x in body.split(';'):
            ps.append(int(x) if x.isdigit() else 0)
        if not ps: ps=[default]
        return ps
    if fin=='H' or fin=='f':
        ps=args()
        r=ps[0] if len(ps)>0 else 1
        c=ps[1] if len(ps)>1 else 1
        sc.cy=min(max(r-1,0),sc.rows-1); sc.cx=min(max(c-1,0),sc.cols-1)
    elif fin=='J':
        ps=args(0); m=ps[0]
        if m==0:
            for x in range(sc.cx,sc.cols): sc.cells[sc.cy][x]=(' ',sc.cur.copy())
            for y in range(sc.cy+1,sc.rows): sc.cells[y]=[(' ',sc.cur.copy()) for _ in range(sc.cols)]
        elif m==1:
            for x in range(0,sc.cx+1): sc.cells[sc.cy][x]=(' ',sc.cur.copy())
            for y in range(0,sc.cy): sc.cells[y]=[(' ',sc.cur.copy()) for _ in range(sc.cols)]
        elif m==2: sc.clear()
    elif fin=='K':
        ps=args(0); m=ps[0]
        if m==0: rng=range(sc.cx,sc.cols)
        elif m==1: rng=range(0,sc.cx+1)
        else: rng=range(sc.cols)
        for x in rng: sc.cells[sc.cy][x]=(' ',sc.cur.copy())
    elif fin=='A':
        sc.cy=max(0,sc.cy-args()[0])
    elif fin=='B':
        sc.cy=min(sc.rows-1,sc.cy+args()[0])
    elif fin=='C':
        sc.cx=min(sc.cols-1,sc.cx+args()[0])
    elif fin=='D':
        sc.cx=max(0,sc.cx-args()[0])
    elif fin=='G':
        sc.cx=min(sc.cols-1,args()[0]-1)
    elif fin=='d':
        sc.cy=min(sc.rows-1,args()[0]-1)
    elif fin=='m':
        sc.cur=parse_sgr(body, sc.cur)
    elif fin=='h' or fin=='l':
        pass
    elif fin=='r':
        pass
    elif fin=='s':
        sc.saved=(sc.cx,sc.cy)
    elif fin=='u':
        try: sc.cx,sc.cy=sc.saved
        except: pass

def render(data, cols=80, rows=24):
    sc=run(data,cols,rows)
    return sc.text_nort()

def render_full(data, cols=80, rows=24):
    sc=run(data,cols,rows)
    return sc.text()
