import os, sys, pty, time, select, fcntl, termios, struct, signal
def run(cmd, keys=(), cols=80, rows=24, delay=0.4, timeout=2.0, stdin=None):
    e=dict(os.environ); e['TERM']='xterm-256color'
    pid, fd = pty.fork()
    if pid==0: os.execvpe(cmd[0],cmd,e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    chunks=[]
    t0=time.time()
    def drain():
        while True:
            r,_,_=select.select([fd],[],[],0.03)
            if not r: return
            try: d=os.read(fd,65536)
            except OSError: return
            if not d: return
            chunks.append((round(time.time()-t0,3), d))
