import os, sys, time, select, fcntl, termios, struct, pty, signal
def go(write_times, args, cols=80, rows=24, timeout=5.0, bin='/workspace/executable'):
    fifo='/tmp/h/f2.fifo'
    try: os.unlink(fifo)
    except: pass
    os.mkfifo(fifo)
    wf=os.open(fifo, os.O_RDWR|os.O_NONBLOCK)
    pid, fd = pty.fork()
    if pid==0:
        os.environ['TERM']='xterm-256color'
        os.execv('/bin/sh', ['sh','-c', bin+' '+' '.join("'%s'"%x for x in args)+' < '+fifo])
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    t0=time.time(); events=[]
    def drain():
        while True:
            r,_,_=select.select([fd],[],[],0.03)
            if not r: return
            try: d=os.read(fd,65536)
            except OSError: return
            if not d: return
            events.append((round(time.time()-t0,3), d))
    drain()
    for t,data in write_times:
        while time.time()-t0 < t: drain()
        os.write(wf, data.encode()); events.append(('WRITE',round(time.time()-t0,3)))
    end=time.time()+timeout
    while time.time()<end: drain()
    try: os.kill(pid, signal.SIGKILL)
    except: pass
    try: os.waitpid(pid,0)
    except: pass
    return events
if __name__=='__main__':
    for T in [0.2, 1.0, 1.5]:
        print('=== T', T)
        for t,d in go([(T,'foo\n')], ['--select-all']):
            print('  ', t, repr(d.decode('utf-8','replace'))[:150])
