def go(actions, args, cols=80, rows=24, timeout=5.0, bin='/workspace/executable'):
    """actions: list of (time, data) to write, or (time,) to close the fifo"""
    fifo='/tmp/h/f2.fifo'
    try: os.unlink(fifo)
    except: pass
    os.mkfifo(fifo)
    wf=os.open(fifo, os.O_RDWR|os.O_NONBLOCK)
    pid, fd = pty.fork()
    if pid==0:
        os.environ['TERM']='xterm-256color'
        os.execv('/bin/sh', ['sh','-c', bin+' '+' '.join("'%s'"%x for x in args)+' < '+fifo])
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    t0=time.time(); events=[]
    def drain():
        while True:
            r,_,_=select.select([fd],[],[],0.03)
            if not r: return
            try: d=os.read(fd,65536)
            except OSError: return
            if not d: return
            events.append((round(time.time()-t0,3), d))
