{"command": "cd /workspace && cat > option/option.go <<'EOF'
// Package option implements a small command line option parser.
//
// The public surface is deliberately tiny: an Option describes a single
// flag, and Parse walks the argument list collecting values.
package option

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Option is a single command line flag.
type Option struct {
	// Names is the list of aliases; the first entry is used when
	// reporting errors involving this flag.
	Names []string
	// HasArg is true when the flag requires a value.
	HasArg bool
	// IsInt is true when the value must parse as an integer.
	IsInt bool
	// Value receives the parsed value.
	Value *string
	// IntValue receives the parsed integer value.
	IntValue *int
}

// ParseError describes a command line parsing failure.
type ParseError struct {
	msg string
}

func (e *ParseError) Error() string { return e.msg }

func (o *Option) name() string {
	if len(o.Names) > 1 {
		return o.Names[0] + ", " + o.Names[1]
	}
	return o.Names[0]
}

func (o *Option) lookup(arg string) (matched bool, inline string, hasInline bool) {
	for _, n := range o.Names {
		if n == arg {
			return true, "", false
		}
		if strings.HasPrefix(n, "--") && strings.HasPrefix(arg, n+"=") {
			return true, arg[len(n)+1:], true
		}
	}
	// short flags may be glued to their value: -b10
	if !strings.HasPrefix(arg, "--") && strings.HasPrefix(arg, "-") && len(arg) > 2 {
		for _, n := range o.Names {
			if !strings.HasPrefix(n, "--") && arg[0:len(n)] == n && len(n) > 1 {
				continue
			}
		}
	}
	return false, "", false
}

// Parser holds the flag definitions for one command line.
type Parser struct {
	opts []*Option
	args []string
	// Help is set when -h/--help was given.
	Help bool
}

// NewParser creates a parser for the given options.
func NewParser(opts []*Option) *Parser {
	return &Parser{opts: opts, args: os.Args[1:]}
}

// Parse walks the arguments.  It returns the list of positional arguments.
func (p *Parser) Parse(args []string) ([]string, error) {
	rest := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if len(arg) < 2 || arg[0] != '-' {
			rest = append(rest, arg)
			continue
		}
		if arg == "-" {
			rest = append(rest, arg)
			continue
		}
		var target *Option
		var inline string
		hasInline := false
		for _, o := range p.opts {
			for _, n := range o.Names {
				if n == arg {
					target = o
					break
				}
				if strings.HasPrefix(n, "--") && strings.HasPrefix(arg, n+"=") {
					target = o
					inline = arg[len(n)+1:]
					hasInline = true
					break
				}
			}
			if target != nil {
				break
			}
		}
		if target == nil {
			// short flag with glued value (-b10)
			if strings.HasPrefix(arg, "-") && !strings.HasPrefix(arg, "--") && len(arg) > 2 {
				if o, ok := p.findShort(arg[0:2]); ok {
					target = o
					inline = arg[2:]
					hasInline = true
				}
			}
		}
		if target == nil {
			name := strings.TrimPrefix(arg, "--")
			if idx := strings.Index(name, "="); idx >= 0 {
				name = name[0:idx]
			}
			return nil, &ParseError{fmt.Sprintf("unknown flag `%s'", name)}
		}
		if !target.HasArg {
			if hasInline {
				return nil, &ParseError{fmt.Sprintf("bool flag `%s' cannot have an argument", target.Names[len(target.Names)-1])}
			}
			if target.Value != nil {
				*target.Value = "true"
			}
			if target.Names[len(target.Names)-1] == "--help" || target.Names[len(target.Names)-1] == "-h" {
				p.Help = true
			}
			continue
		}
		val := inline
		if !hasInline {
			if i >= len(args) {
				return nil, &ParseError{fmt.Sprintf("expected argument for flag `%s'", target.name())}
			}
			val = args[i]
			i++
		}
		if target.IsInt {
			n, err := strconv.ParseInt(val, 10, 64)
			if err != nil {
				return nil, &ParseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", target.name(), err.Error())}
			}
			*target.IntValue = int(n)
		}
		if target.Value != nil {
			*target.Value = val
		}
	}
	return rest, nil
}

func (p *Parser) findShort(prefix string) (*Option, bool) {
	for _, o := range p.opts {
		for _, n := range o.Names {
			if n == prefix && !strings.HasPrefix(n, "--") {
				return o, true
			}
		}
	}
	return nil, false
}
