func (p *Parser) findShort(prefix string) (*Option, bool) {
	for _, o := range p.opts {
		for _, n := range o.Names {
			if n == prefix && !strings.HasPrefix(n, "--") {
				return o, true
			}
		}
	}
	return nil, false
}
