{"command": "cd /workspace && cat > config/config.go <<'EOF'
// Package config holds the user configurable knobs of peco.
package config

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// OnCancelBehavior describes what happens when the user cancels.
type OnCancelBehavior string

const (
	// OnCancelSuccess exits with status 0 (the historical default).
	OnCancelSuccess OnCancelBehavior = "success"
	// OnCancelError exits with a non zero status.
	OnCancelError OnCancelBehavior = "error"
)

// CustomFilterConfig describes an external filter process.
type CustomFilterConfig struct {
	Cmd             string
	Args            []string
	BufferThreshold int
}

// SingleKeyJumpConfig configures the SingleKeyJump mode.
type SingleKeyJumpConfig struct {
	ShowPrefix bool
}

// Style is a resolved set of colors and attributes.
type Style struct {
	// fg and bg are either a color or ColorUnset.
	fg    int
	bg    int
	attrs uint32
	set   bool
}

// ColorUnset marks a color slot as not specified by the user.
const ColorUnset = -2

// ColorDefault maps to the terminal default color.
const ColorDefault = -1

// Attribute bit masks.
const (
	AttrBold      uint32 = 1 << iota
	AttrUnderline
	AttrReverse
	AttrBlink
	AttrItalic
	AttrStrike
)

// IsZero returns true when the style was never mentioned in the config.
func (s Style) IsZero() bool { return !s.set }

// FG returns the foreground color, or ColorDefault when unset.
func (s Style) FG() int {
	if s.fg == ColorUnset {
		return ColorDefault
	}
	return s.fg
}

// BG returns the background color, or ColorDefault when unset.
func (s Style) BG() int {
	if s.bg == ColorUnset {
		return ColorDefault
	}
	return s.bg
}

// Attrs returns the attribute mask.
func (s Style) Attrs() uint32 { return s.attrs }

// Has returns true when the token was mentioned for this style.
func (s Style) HasFG() bool { return s.fg != ColorUnset }

// HasBG returns true when a background color was specified.
func (s Style) HasBG() bool { return s.bg != ColorUnset }

// ParseStyle builds a Style out of a list of tokens such as
// "bold", "on_blue" or "#ff0044".
func ParseStyle(colors []string) (Style, error) {
	s := Style{fg: ColorUnset, bg: ColorUnset}
	for _, c := range colors {
		switch {
		case c == "on_default":
			s.bg = ColorDefault
		case strings.HasPrefix(c, "on_"):
			n, err := parseColor(c[3:])
			if err != nil {
				return s, err
			}
			s.bg = n
		case c == "default":
			s.fg = ColorDefault
		case c == "bold":
			s.attrs |= AttrBold
		case c == "underline":
			s.attrs |= AttrUnderline
		case c == "reverse":
			s.attrs |= AttrReverse
		case c == "blink":
			s.attrs |= AttrBlink
		case c == "italic":
			s.attrs |= AttrItalic
		case c == "strike":
			s.attrs |= AttrStrike
		case c == "on_bold":
			s.attrs |= AttrBold
		default:
			n, err := parseColor(c)
			if err != nil {
				return s, err
			}
			s.fg = n
		}
	}
	return s, nil
}

func parseColor(name string) (int, error) {
	switch name {
	case "black":
		return 0, nil
	case "maroon", "red":
		return 1, nil
	case "green":
		return 2, nil
	case "olive", "yellow":
		return 3, nil
	case "navy", "blue":
		return 4, nil
	case "purple", "magenta":
		return 5, nil
	case "teal", "cyan":
		return 6, nil
	case "silver", "white":
		return 7, nil
	case "gray", "grey":
		return 8, nil
	}
	if len(name) == 1 && name[0] >= '0' && name[0] <= '9' {
		return int(name[0] - '0'), nil
	}
	if len(name) == 2 || len(name) == 3 {
		ok := true
		for i := 0; i < len(name); i++ {
			if name[i] < '0' || name[i] > '9' {
				ok = false
				break
			}
		}
		if ok {
			var n int
			for i := 0; i < len(name); i++ {
				n = n*10 + int(name[i]-'0')
			}
			if n <= 255 {
				return n, nil
			}
		}
	}
	if strings.HasPrefix(name, "#") && (len(name) == 7 || len(name) == 4) {
		var r, g, b int
		hex := func(s string) int {
			v := 0
			for i := 0; i < len(s); i++ {
				c := s[i]
				switch {
				case c >= '0' && c <= '9':
					v = v*16 + int(c-'0')
				case c >= 'a' && c <= 'f':
					v = v*16 + int(c-'a') + 10
				case c >= 'A' && c <= 'F':
					v = v*16 + int(c-'A') + 10
				default:
					return -1
				}
			}
			return v
		}
		if len(name) == 7 {
			r = hex(name[1:3])
			g = hex(name[3:5])
			b = hex(name[5:7])
		} else {
			r = hex(name[1:2]) * 17
			g = hex(name[2:3]) * 17
			b = hex(name[3:4]) * 17
		}
		if r < 0 || g < 0 || b < 0 {
			return 0, fmt.Errorf("unknown color name: %s", name)
		}
		return 0x1000000 | (r << 16) | (g << 8) | b, nil
	}
	return 0, fmt.Errorf("unknown color name: %s", name)
}

// StyleSet holds all the named styles peco uses.
type StyleSet struct {
	Basic          Style
	SavedSelection Style
	Selected       Style
	Query          Style
	QueryCursor    Style
	Matched        Style
	Prompt         Style
	Context        Style
}

// UnmarshalJSON implements a permissive decoding of the Style section.
func (s *StyleSet) UnmarshalJSON(data []byte) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("failed to unmarshal Style: %v", err)
	}
	for k, v := range raw {
		var list []string
		if err := json.Unmarshal(v, &list); err != nil {
			return fmt.Errorf("failed to unmarshal Style: %v", err)
		}
		st, err := ParseStyle(list)
		if err != nil {
			return fmt.Errorf("failed to unmarshal Style: %v", err)
		}
		switch strings.ToLower(k) {
		case "basic":
			s.Basic = st
		case "savedselection":
			s.SavedSelection = st
		case "selected":
			s.Selected = st
		case "query":
			s.Query = st
		case "querycursor":
			s.QueryCursor = st
		case "matched":
			s.Matched = st
		case "prompt":
			s.Prompt = st
		case "context":
			s.Context = st
		}
	}
	return nil
}

// Config is the root of the configuration file.
type Config struct {
	InitialFilter     string
	Prompt            string
	Keymap            map[string]string
	Style             StyleSet
	Action            map[string][]string
	Layout            string
	OnCancel          OnCancelBehavior
	FuzzyLongestSort  bool
	StickySelection   bool
	SuppressStatusMsg bool
	MaxScanBufferSize int
	ANSI              bool
	Height            string
	SelectionPrefix   string
	SingleKeyJump     SingleKeyJumpConfig
	CustomFilter      map[string]CustomFilterConfig
}

// NewConfig returns a Config with all the defaults filled in.
func NewConfig() *Config {
	return &Config{
		InitialFilter:     "IgnoreCase",
		Prompt:            "QUERY> ",
		Keymap:            map[string]string{},
		Action:            map[string][]string{},
		Layout:            "top-down",
		OnCancel:          OnCancelSuccess,
		MaxScanBufferSize: 256,
		CustomFilter:      map[string]CustomFilterConfig{},
	}
}

// Read loads a config file, dispatching on the file extension.
func Read(fn string) (*Config, error) {
	fp, err := os.Open(fn)
	if err != nil {
		return nil, fmt.Errorf("failed to open file %s: %w", fn, err)
	}
	defer fp.Close()

	ext := strings.ToLower(filepath.Ext(fn))
	if ext == ".yaml" || ext == ".yml" {
		return decodeYAML(fp)
	}
	return decodeJSON(fp)
}

func decodeJSON(r io.Reader) (*Config, error) {
	c := NewConfig()
	d := json.NewDecoder(r)
	if err := d.Decode(c); err != nil {
		return nil, fmt.Errorf("failed to decode JSON: %w", err)
	}
	return c, nil
}
EOF
echo ok"}

