func parseColor(name string) (int, error) {
	switch name {
	case "black":
		return 0, nil
	case "maroon", "red":
		return 1, nil
	case "green":
		return 2, nil
	case "olive", "yellow":
		return 3, nil
	case "navy", "blue":
		return 4, nil
	case "purple", "magenta":
		return 5, nil
	case "teal", "cyan":
		return 6, nil
	case "silver", "white":
		return 7, nil
	case "gray", "grey":
		return 8, nil
	}
	if len(name) == 1 && name[0] >= '0' && name[0] <= '9' {
		return int(name[0] - '0'), nil
	}
	if len(name) == 2 || len(name) == 3 {
		ok := true
		for i := 0; i < len(name); i++ {
			if name[i] < '0' || name[i] > '9' {
				ok = false
				break
			}
		}
		if ok {
			var n int
			for i := 0; i < len(name); i++ {
				n = n*10 + int(name[i]-'0')
			}
			if n <= 255 {
				return n, nil
			}
		}
	}
	if strings.HasPrefix(name, "#") && (len(name) == 7 || len(name) == 4) {
		var r, g, b int
		hex := func(s string) int {
			v := 0
			for i := 0; i < len(s); i++ {
				c := s[i]
				switch {
				case c >= '0' && c <= '9':
					v = v*16 + int(c-'0')
				case c >= 'a' && c <= 'f':
					v = v*16 + int(c-'a') + 10
				case c >= 'A' && c <= 'F':
					v = v*16 + int(c-'A') + 10
				default:
					return -1
				}
			}
			return v
		}
		if len(name) == 7 {
			r = hex(name[1:3])
			g = hex(name[3:5])
			b = hex(name[5:7])
		} else {
			r = hex(name[1:2]) * 17
			g = hex(name[2:3]) * 17
			b = hex(name[3:4]) * 17
		}
		if r < 0 || g < 0 || b < 0 {
			return 0, fmt.Errorf("unknown color name: %s", name)
		}
		return 0x1000000 | (r << 16) | (g << 8) | b, nil
	}
	return 0, fmt.Errorf("unknown color name: %s", name)
