// yamlError carries the position information goccy-style errors need.
type yamlError struct {
	line, col int
	msg       string
	lines     []string
}

func (e *yamlError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "[%d:%d] %s\n", e.line, e.col, e.msg)
	width := len(fmt.Sprintf("%d", len(e.lines)))
	for i, l := range e.lines {
		n := i + 1
		marker := "  "
		if n == e.line {
			marker = "> "
		}
		fmt.Fprintf(&b, "%s%*d | %s\n", marker, width, n, l)
		if n == e.line {
			fmt.Fprintf(&b, "%s%s^\n", strings.Repeat(" ", width+4), strings.Repeat(" ", e.col-1))
		}
	}
	b.WriteString("\n")
	return b.String()
}

type yline struct {
	raw    string
	indent int
	num    int
	body   string // raw with the indent removed
}

type yparser struct {
	lines []yline
	i     int
	src   []string
}

func newYParser(src string) *yparser {
	p := &yparser{src: strings.Split(src, "\n")}
	for i, l := range p.src {
		l = strings.TrimRight(l, "\r")
		trimmed := strings.TrimLeft(l, " ")
		indent := len(l) - len(trimmed)
		p.lines = append(p.lines, yline{raw: l, indent: indent, num: i + 1, body: trimmed})
	}
	return p
}

func (p *yparser) errAt(l, c int, msg string) error {
	return &yamlError{line: l, col: c, msg: msg, lines: p.src}
}

// stripComment removes a trailing comment from a plain scalar region.
func stripComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inD {
				inS = !inS
			}
		case '"':
			if !inS {
				inD = !inD
			}
		case '#':
			if !inS && !inD && (i == 0 || s[i-1] == ' ' || s[i-1] == '\t') {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return s
}

func (p *yparser) skipBlank() {
	for p.i < len(p.lines) {
		l := p.lines[p.i]
		if l.body == "" || strings.HasPrefix(l.body, "#") {
			p.i++
			continue
		}
		return
	}
}

// value holds a parsed node plus its source position.
type ynode struct {
	val   interface{}
	line  int
	col   int
}

// Parse parses the document into a tree of ynode values.
func (p *yparser) parseBlock(minIndent int) (interface{}, int, int, error) {
	p.skipBlank()
	if p.i >= len(p.lines) {
		return nil, 0, 0, nil
	}
	l := p.lines[p.i]
	if l.indent < minIndent {
		return nil, 0, 0, nil
	}
	if strings.HasPrefix(l.body, "- ") || l.body == "-" {
		return p.parseSeq(l.indent)
	}
	return p.parseMap(l.indent)
}

func (p *yparser) parseMap(indent int) (interface{}, int, int, error) {
	m := map[string]*ynode{}
	order := []string{}
	firstLine, firstCol := 0, 0
	for {
		p.skipBlank()
		if p.i >= len(p.lines) {
			break
		}
		l := p.lines[p.i]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, 0, 0, p.errAt(l.num, l.indent+1, "mapping value is not allowed in this context")
		}
		if strings.HasPrefix(l.body, "- ") || l.body == "-" {
			break
		}
		key, rest, kcol, ok := splitKey(l.body)
		if !ok {
			return nil, 0, 0, p.errAt(l.num, l.indent+1, "could not find expected ':'")
		}
		if firstLine == 0 {
			firstLine, firstCol = l.num, l.indent+kcol+1
		}
		if _, dup := m[key]; dup {
			return nil, 0, 0, p.errAt(l.num, l.indent+1,
				fmt.Sprintf("mapping key %q already defined at [%d:%d]", key, firstLine, firstCol))
		}
		p.i++
		rest = strings.TrimSpace(stripComment(rest))
		if rest != "" {
			v, err := p.parseInline(rest, l.num, l.indent+kcol+2)
			if err != nil {
				return nil, 0, 0, err
			}
			m[key] = &ynode{val: v, line: l.num, col: l.indent + kcol + 2}
			order = append(order, key)
			continue
		}
		// look at the next line to decide whether this is a nested block
		p.skipBlank()
		if p.i < len(p.lines) && p.lines[p.i].indent > indent {
			v, _, _, err := p.parseBlock(indent + 1)
			if err != nil {
				return nil, 0, 0, err
			}
			m[key] = &ynode{val: v, line: l.num, col: l.indent + kcol + 2}
		} else {
			m[key] = &ynode{val: nil, line: l.num, col: l.indent + kcol + 2}
		}
		order = append(order, key)
	}
	return m, firstLine, firstCol, nil
}

func (p *yparser) parseSeq(indent int) (interface{}, int, int, error) {
	var out []*ynode
	firstLine, firstCol := 0, 0
	for {
		p.skipBlank()
		if p.i >= len(p.lines) {
			break
		}
		l := p.lines[p.i]
		if l.indent != indent || !(strings.HasPrefix(l.body, "- ") || l.body == "-") {
			break
		}
		if firstLine == 0 {
			firstLine, firstCol = l.num, l.indent+1
		}
		rest := ""
		if l.body != "-" {
			rest = strings.TrimSpace(l.body[2:])
		}
		p.i++
		rest = strings.TrimSpace(stripComment(rest))
		if rest != "" {
			v, err := p.parseInline(rest, l.num, l.indent+3)
			if err != nil {
				return nil, 0, 0, err
			}
			out = append(out, &ynode{val: v, line: l.num, col: l.indent + 3})
			continue
		}
		p.skipBlank()
		if p.i < len(p.lines) && p.lines[p.i].indent > indent {
			v, _, _, err := p.parseBlock(indent + 1)
			if err != nil {
				return nil, 0, 0, err
			}
			out = append(out, &ynode{val: v, line: l.num, col: l.indent + 3})
		} else {
			out = append(out, &ynode{val: nil, line: l.num, col: l.indent + 3})
		}
	}
	return out, firstLine, firstCol, nil
}

func splitKey(s string) (key, rest string, col int, ok bool) {
	// keys may be quoted
	if len(s) > 0 && (s[0] == '"' || s[0] == '\'') {
		q := s[0]
		i := 1
		for i < len(s) {
			if s[i] == '\\' && q == '"' {
				i += 2
				continue
			}
			if s[i] == q {
				break
			}
			i++
		}
		if i >= len(s) {
			return "", "", 0, false
		}
		k, err := unquote(s[:i+1])
		if err != nil {
			return "", "", 0, false
		}
		rest = s[i+1:]
		col = i + 2
		if strings.HasPrefix(rest, ":") {
			return k, rest[1:], col, true
		}
		return "", "", 0, false
	}
	idx := strings.Index(s, ":")
	if idx < 0 {
		return "", "", 0, false
	}
	if idx+1 < len(s) && s[idx+1] != ' ' {
		// "a:b" style is not a mapping
		return "", "", 0, false
	}
	return strings.TrimRight(s[:idx], " \t"), s[idx+1:], idx + 1, true
}

func unquote(s string) (string, error) {
	if len(s) < 2 {
		return s, nil
	}
	q := s[0]
	body := s[1 : len(s)-1]
	if q == '\'' {
		return strings.ReplaceAll(body, "''", "'"), nil
	}
	var b strings.Builder
	for i := 0; i < len(body); i++ {
		if body[i] != '\\' || i+1 >= len(body) {
			b.WriteByte(body[i])
			continue
		}
		i++
		switch body[i] {
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'r':
			b.WriteByte('\r')
		case '0':
			b.WriteByte(0)
		case '\\':
			b.WriteByte('\\')
		case '"':
			b.WriteByte('"')
		default:
			b.WriteByte(body[i])
		}
	}
	return b.String(), nil
}

// parseInline parses a scalar or a flow collection on a single line.
func (p *yparser) parseInline(s string, line, col int) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	switch s[0] {
	case '[':
		if !strings.HasSuffix(s, "]") {
			return nil, p.errAt(line, col+len(s), "sequence end token ']' not found")
		}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		var out []*ynode
		if inner != "" {
			for _, part := range splitFlow(inner) {
				v, err := p.parseInline(part, line, col)
				if err != nil {
					return nil, err
				}
				out = append(out, &ynode{val: v, line: line, col: col})
			}
		}
		return out, nil
	case '{':
		if !strings.HasSuffix(s, "}") {
			return nil, p.errAt(line, col+len(s), "mapping end token '}' not found")
		}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		m := map[string]*ynode{}
		if inner != "" {
			for _, part := range splitFlow(inner) {
				k, rest, _, ok := splitKey(strings.TrimSpace(part))
				if !ok {
					return nil, p.errAt(line, col, "could not find expected ':'")
				}
				v, err := p.parseInline(rest, line, col)
				if err != nil {
					return nil, err
				}
				m[k] = &ynode{val: v, line: line, col: col}
			}
		}
		return m, nil
	case '"', '\'':
		if len(s) < 2 || s[len(s)-1] != s[0] {
			return nil, p.errAt(line, col+len(s), fmt.Sprintf("could not find end character of %q", string(s[0])))
		}
		return mustUnquote(s), nil
	}
	if strings.HasPrefix(s, "|") || strings.HasPrefix(s, ">") {
		// block scalar: gather the following more indented lines
		var parts []string
		for p.i < len(p.lines) && p.lines[p.i].indent > 0 {
			parts = append(parts, p.lines[p.i].raw)
			p.i++
		}
		sep := "\n"
		if s[0] == '>' {
			sep = " "
		}
		return strings.Join(parts, sep), nil
	}
	return scalarValue(s), nil
}

func mustUnquote(s string) string {
	v, _ := unquote(s)
	return v
}

func splitFlow(s string) []string {
	var out []string
	depth := 0
	inS, inD := false, false
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inD {
				inS = !inS
			}
		case '"':
			if !inS {
				inD = !inD
			}
		case '[', '{':
			if !inS && !inD {
				depth++
			}
		case ']', '}':
			if !inS && !inD {
				depth--
			}
		case ',':
			if depth == 0 && !inS && !inD {
				out = append(out, strings.TrimSpace(s[start:i]))
				start = i + 1
			}
		}
	}
	out = append(out, strings.TrimSpace(s[start:]))
	return out
}

func scalarValue(s string) interface{} {
	switch s {
	case "~", "null", "Null", "NULL":
		return nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON":
		return true
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF":
		return false
	}
	if n, err := strconv.ParseUint(s, 10, 64); err == nil {
		return n
	}
	if n, err := strconv.ParseInt(s, 10, 64); err == nil {
		return n
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f
	}
	return s
}

// decodeYAML reads a YAML document and turns it into a Config.
func decodeYAML(r io.Reader) (*Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read YAML: %w", err)
	}
	p := newYParser(string(data))
	v, _, _, err := p.parseBlock(0)
	if err != nil {
		return nil, err
	}
	c := NewConfig()
	if v == nil {
		return c, nil
	}
	m, ok := v.(map[string]*ynode)
	if !ok {
		return nil, p.errAt(1, 1, "cannot unmarshal into Go struct field Config")
	}
	if err := decodeYAMLNode(p, m, c); err != nil {
		return nil, err
	}
	return c, nil
}

func typeOf(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case uint64:
		return "uint64"
	case int64:
		return "int64"
	case float64:
		return "float64"
	case bool:
		return "bool"
	case string:
		return "string"
	case []*ynode:
		return "[]interface {}"
	case map[string]*ynode:
		return "map[string]interface {}"
	default:
		return fmt.Sprintf("%T", t)
	}
}
