func decodeYAMLNode(p *yparser, m map[string]*ynode, c *Config) error {
	for _, f := range []struct {
		name string
		kind string
	}{
		{"InitialFilter", "string"},
		{"Prompt", "string"},
		{"Keymap", "map[string]string"},
		{"Style", "config.StyleSet"},
		{"Action", "map[string][]string"},
		{"Layout", "string"},
		{"OnCancel", "config.OnCancelBehavior"},
		{"FuzzyLongestSort", "bool"},
		{"StickySelection", "bool"},
		{"SuppressStatusMsg", "bool"},
		{"MaxScanBufferSize", "int"},
		{"ANSI", "bool"},
		{"Height", "string"},
		{"SelectionPrefix", "string"},
		{"SingleKeyJump", "config.SingleKeyJumpConfig"},
		{"CustomFilter", "map[string]config.CustomFilterConfig"},
	} {
		n, ok := m[f.name]
		if !ok {
			continue
		}
		if n.val == nil {
			continue
		}
		switch f.name {
		case "Prompt":
			s, err := asString(n, "Config.Prompt")
			if err != nil {
				return err
			}
			c.Prompt = s
		case "InitialFilter":
			s, err := asString(n, "Config.InitialFilter")
			if err != nil {
				return err
			}
			c.InitialFilter = s
		case "Layout":
			s, err := asString(n, "Config.Layout")
			if err != nil {
				return err
			}
			c.Layout = s
		case "Height":
			s, err := asString(n, "Config.Height")
			if err != nil {
				return err
			}
			c.Height = s
		case "SelectionPrefix":
			s, err := asString(n, "Config.SelectionPrefix")
			if err != nil {
				return err
			}
			c.SelectionPrefix = s
		case "OnCancel":
			s, err := asString(n, "Config.OnCancel")
			if err != nil {
				return err
			}
			c.OnCancel = OnCancelBehavior(s)
		case "ANSI":
			b, err := asBool(n, "Config.ANSI")
			if err != nil {
				return err
			}
			c.ANSI = b
		case "FuzzyLongestSort":
			b, err := asBool(n, "Config.FuzzyLongestSort")
			if err != nil {
				return err
			}
			c.FuzzyLongestSort = b
		case "StickySelection":
			b, err := asBool(n, "Config.StickySelection")
			if err != nil {
				return err
			}
			c.StickySelection = b
		case "SuppressStatusMsg":
			b, err := asBool(n, "Config.SuppressStatusMsg")
			if err != nil {
				return err
			}
			c.SuppressStatusMsg = b
		case "MaxScanBufferSize":
			v, err := asInt(n, "Config.MaxScanBufferSize")
			if err != nil {
				return err
			}
			c.MaxScanBufferSize = v
		case "Keymap":
			mm, err := asStringMap(n, "Config.Keymap", "map[string]string")
			if err != nil {
				return err
			}
			c.Keymap = mm
		case "Action":
			mm, ok := n.val.(map[string]*ynode)
			if !ok {
				return p.typeErr(n, "Config.Action", "map[string][]string")
			}
			c.Action = map[string][]string{}
			for k, v := range mm {
				l, err := asStringSlice(v, "Config.Action")
				if err != nil {
					return err
				}
				c.Action[k] = l
			}
		case "Style":
			sm, ok := n.val.(map[string]*ynode)
			if !ok {
				return fmt.Errorf("failed to unmarshal Style from YAML: %s", p.typeErr(n, "config.StyleSet", "map[string]interface {}").Error())
			}
			for k, v := range sm {
				list, ok := v.val.([]*ynode)
				if !ok {
					return fmt.Errorf("failed to unmarshal Style from YAML: %s",
						p.errAt(v.line, v.col, "string was used where sequence is expected").Error())
				}
				var toks []string
				for _, it := range list {
					s, err := asString(it, "Style."+k)
					if err != nil {
						return err
					}
					toks = append(toks, s)
				}
				st, err := ParseStyle(toks)
				if err != nil {
					return err
				}
				switch strings.ToLower(k) {
				case "basic":
					c.Style.Basic = st
				case "savedselection":
					c.Style.SavedSelection = st
				case "selected":
					c.Style.Selected = st
				case "query":
					c.Style.Query = st
				case "querycursor":
					c.Style.QueryCursor = st
				case "matched":
					c.Style.Matched = st
				case "prompt":
					c.Style.Prompt = st
				case "context":
					c.Style.Context = st
				}
			}
		case "SingleKeyJump":
			sm, ok := n.val.(map[string]*ynode)
			if !ok {
				return p.typeErr(n, "Config.SingleKeyJump", "config.SingleKeyJumpConfig")
			}
			for k, v := range sm {
				switch strings.ToLower(k) {
				case "showprefix":
					b, err := asBool(v, "SingleKeyJumpConfig.SingleKeyJump.ShowPrefix")
					if err != nil {
						return err
					}
					c.SingleKeyJump.ShowPrefix = b
				}
			}
		case "CustomFilter":
			sm, ok := n.val.(map[string]*ynode)
			if !ok {
				return p.typeErr(n, "Config.CustomFilter", "map[string]config.CustomFilterConfig")
			}
			c.CustomFilter = map[string]CustomFilterConfig{}
			for k, v := range sm {
				fc := CustomFilterConfig{}
				fm, ok := v.val.(map[string]*ynode)
				if !ok {
					return p.typeErr(v, "Config.CustomFilter", "config.CustomFilterConfig")
				}
				for fk, fv := range fm {
					switch fk {
					case "Cmd":
						s, err := asString(fv, "CustomFilterConfig.CustomFilter.Cmd")
						if err != nil {
							return err
						}
						fc.Cmd = s
					case "Args":
						l, err := asStringSlice(fv, "CustomFilterConfig.CustomFilter.Args")
						if err != nil {
							return err
						}
						fc.Args = l
					case "BufferThreshold":
						i, err := asInt(fv, "CustomFilterConfig.CustomFilter.BufferThreshold")
						if err != nil {
							return err
						}
						fc.BufferThreshold = i
					}
				}
				c.CustomFilter[k] = fc
			}
		}
	}
	return nil
}
