func (p *yparser) typeErr(n *ynode, field, want string) error {
	return p.errAt(n.line, n.col,
		fmt.Sprintf("cannot unmarshal %s into Go struct field %s of type %s", typeOf(n.val), field, want))
}

func asString(n *ynode, field string) (string, error) {
	switch t := n.val.(type) {
	case nil:
		return "", nil
	case string:
		return t, nil
	case uint64:
		return strconv.FormatUint(t, 10), nil
	case int64:
