	}
	return false, p.typeErr(n, field, "bool")
}

func asInt(n *ynode, field string) (int, error) {
	switch t := n.val.(type) {
	case uint64:
		return int(t), nil
	case int64:
		return int(t), nil
	case float64:
		return int(t), nil
