// Package option implements the small command line option parser peco uses.
//
// The public surface is deliberately tiny: an Option describes a single
// flag and Parse walks the argument list collecting values.  Error messages
// are formatted to match peco's expectations.
package option

import (
	"fmt"
	"strconv"
	"strings"
)

// Option is a single command line flag.
type Option struct {
	// Names is the list of aliases.  The first two are used when reporting
	// errors ("--query" or "-b, --buffer-size").
	Names []string
	// HasArg is true when the flag requires a value.
	HasArg bool
	// IsInt is true when the value must parse as an integer.
	IsInt bool
	// Value receives the raw string value.
	Value *string
	// IntValue receives the parsed integer value.
	IntValue *int
}

// ParseError describes a command line parsing failure.
type ParseError struct{ msg string }

func (e *ParseError) Error() string { return e.msg }

func (o *Option) displayName() string {
	if len(o.Names) > 1 {
		return o.Names[0] + ", " + o.Names[1]
	}
	return o.Names[0]
}

func (o *Option) isHelp() bool {
	for _, n := range o.Names {
		if n == "-h" || n == "--help" {
			return true
		}
	}
	return false
}

// looksLikeOption reports whether arg should be rejected as a value.
func looksLikeOption(arg string, isInt bool) bool {
	if arg == "-" || arg == "--" {
		return false
	}
	if strings.HasPrefix(arg, "--") {
		return true
	}
	if strings.HasPrefix(arg, "-") {
		return !isInt
	}
	return false
}

// Parser holds the flag definitions for one command line.
type Parser struct {
	opts []*Option
	// Help is set when -h/--help was given.
	Help bool
}

// NewParser creates a parser for the given options.
func NewParser(opts []*Option) *Parser { return &Parser{opts: opts} }

func (p *Parser) find(arg string) (*Option, bool, string) {
	for _, o := range p.opts {
		for _, n := range o.Names {
			if n == arg {
				return o, false, ""
			}
			if strings.HasPrefix(n, "--") && strings.HasPrefix(arg, n+"=") {
				return o, true, arg[len(n)+1:]
			}
		}
	}
	return nil, false, ""
}

// Parse walks the arguments, returning the positional arguments.
func (p *Parser) Parse(args []string) ([]string, error) {
	rest := []string{}
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if len(arg) < 2 || arg[0] != '-' || arg == "--" {
			rest = append(rest, arg)
			continue
		}
		if strings.HasPrefix(arg, "--") {
			o, inline, val := p.find(arg)
			if o == nil {
				return nil, &ParseError{fmt.Sprintf("unknown flag `%s'", strings.SplitN(arg[2:], "=", 2)[0])}
			}
			v, err := p.consume(o, inline, val, args, &i)
			if err != nil {
				return nil, err
			}
			_ = v
			continue
		}
		// short flags: -h, -b5, -hb
		body := arg[1:]
		for len(body) > 0 {
			ch := body[0:1]
			o, inline, val := p.find("-" + ch)
			if o == nil {
				return nil, &ParseError{fmt.Sprintf("unknown flag `%s'", ch)}
			}
			if o.HasArg {
				rest := body[1:]
				if rest != "" {
					if _, err := p.assign(o, rest); err != nil {
						return nil, err
					}
					body = ""
					continue
				}
				if _, err := p.consume(o, false, "", args, &i); err != nil {
					return nil, err
				}
				body = ""
				continue
			}
			if _, err := p.assign(o, ""); err != nil {
				return nil, err
			}
			body = body[1:]
		}
	}
	return rest, nil
}

func (p *Parser) consume(o *Option, hasInline bool, inline string, args []string, i *int) (string, error) {
	if !o.HasArg {
		if hasInline {
			return "", &ParseError{fmt.Sprintf("bool flag `%s' cannot have an argument", o.displayName())}
		}
		return p.assign(o, "")
	}
	val := inline
	if !hasInline {
		if *i >= len(args) {
			return "", &ParseError{fmt.Sprintf("expected argument for flag `%s'", o.displayName())}
		}
		next := args[*i]
		if looksLikeOption(next, o.IsInt) {
			return "", &ParseError{fmt.Sprintf("expected argument for flag `%s', but got option `%s'", o.displayName(), next)}
		}
		*i++
		val = next
	}
	return p.assign(o, val)
}

func (p *Parser) assign(o *Option, val string) (string, error) {
	if o.isHelp() && !o.HasArg {
		p.Help = true
	}
	if o.IsInt {
		n, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return "", &ParseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", o.displayName(), err.Error())}
		}
		if o.IntValue != nil {
			*o.IntValue = int(n)
		}
	}
	if o.Value != nil {
		*o.Value = val
	}
	return val, nil
}
