{"command": "cd /workspace && mkdir -p peco && cat > peco/buffer.go <<'EOF'
package peco

import (
	"bufio"
	"io"
	"strings"
)

// Line is one line of the input buffer.
type Line struct {
	// Display is the string that is matched and rendered.
	Display string
	// Raw is the string that is printed when the line is selected.
	Raw string
	// Annotated holds the SGR colored segments of the line when the
	// --ansi flag is in effect.
	Annotated []Segment
}

// Segment is a run of text with an attached SGR attribute string.
type Segment struct {
	Text string
	Attr string
}

// NewLine creates a Line from a raw input string.
func NewLine(raw string) *Line {
	return &Line{Display: raw, Raw: raw}
}

// Buffer holds all the input lines.
type Buffer struct {
	lines []*Line
}

// NewBuffer creates an empty buffer.
func NewBuffer() *Buffer { return &Buffer{} }

// Lines returns the buffered lines.
func (b *Buffer) Lines() []*Line { return b.lines }

// Add appends lines to the buffer.
func (b *Buffer) Add(ls []*Line) { b.lines = append(b.lines, ls...) }

// Length returns the number of buffered lines.
func (b *Buffer) Length() int { return len(b.lines) }

// At returns the line at the given index.
func (b *Buffer) At(i int) *Line {
	if i < 0 || i >= len(b.lines) {
		return nil
	}
	return b.lines[i]
}

// reader turns a stream into lines, calling add for each chunk read.
type reader struct {
	scanner   *bufio.Scanner
	ch        chan []*Line
	done      chan struct{}
	nullSep   bool
}

func newReader(r io.Reader, nullSep bool) *reader {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 256*1024), 64*1024*1024)
	rd := &reader{scanner: sc, ch: make(chan []*Line, 1), done: make(chan struct{}), nullSep: nullSep}
	return rd
}

// splitLines splits the chunk into lines; a trailing incomplete line is
// returned as pending.
func splitLines(data string) (lines []string, pending string) {
	if data == "" {
		return nil, ""
	}
	for {
		i := strings.IndexByte(data, '\n')
		if i < 0 {
			return nil, data
		}
		l := data[:i]
		l = strings.TrimSuffix(l, "\r")
		lines = append(lines, l)
		data = data[i+1:]
	}
}
EOF
echo ok"}

