import sys
sys.path.insert(0,'/tmp/h')
from ff import go
import ansi
def cells(args, data, wait=0.7):
    d=go(args, write=data, write_at=0.2, wait=wait)
    sc=ansi.run(d,80,24)
    out=[]
    for r in sc.cells[1:]:
        t=''.join(c[0] for c in r).rstrip()
        if not t: continue
        runs=[]
        cur=None; start=0
        for i,(ch,st) in enumerate(r):
            k=st.key()
            if k!=cur:
                if cur is not None: runs.append((start,i))
                cur=k; start=i
            if ch==' ' and st.key()==(None,None,False,False,False,False,False,False): break
        if cur is not None: runs.append((start,len(t)))
        out.append((t,runs))
    return out
