{"command": "cd /workspace && cat > peco/filter.go <<'EOF'
package peco

import (
	"regexp"
	"strings"
)

// FilterKind identifies one of the builtin filters.
type FilterKind int

// The builtin filters.
const (
	IgnoreCase FilterKind = iota
	CaseSensitive
	SmartCase
	IRegexp
	Regexp
	Fuzzy
)

var filterNames = map[string]FilterKind{
	"IgnoreCase":    IgnoreCase,
	"CaseSensitive": CaseSensitive,
	"SmartCase":     SmartCase,
	"IRegexp":       IRegexp,
	"Regexp":        Regexp,
	"Fuzzy":         Fuzzy,
}

var filterDisplay = map[FilterKind]string{
	IgnoreCase:    "IgnoreCase",
	CaseSensitive: "CaseSensitive",
	SmartCase:     "SmartCase",
	IRegexp:       "IRegexp",
	Regexp:        "Regexp",
	Fuzzy:         "Fuzzy",
}

// FilterName returns the display name of the filter.
func FilterName(k FilterKind) string { return filterDisplay[k] }

// FilterFromName looks a filter up by its config name.
func FilterFromName(name string) (FilterKind, bool) {
	k, ok := filterNames[name]
	return k, ok
}

// term is one whitespace separated chunk of the query.
type term struct {
	text string
	neg  bool
}

// parseQuery splits the query into positive and negative terms.
func parseQuery(q string) []term {
	var out []term
	for _, s := range strings.Fields(q) {
		switch {
		case s == "-":
			out = append(out, term{text: "-"})
		case strings.HasPrefix(s, "\\-"):
			out = append(out, term{text: strings.TrimPrefix(s, "\\")})
		case strings.HasPrefix(s, "-"):
			out = append(out, term{text: s[1:], neg: true})
		default:
			out = append(out, term{text: s})
		}
	}
	return out
}

// Match is one matching line plus the ranges to highlight.
type Match struct {
	Line   *Line
	Ranges []int
}

// Matcher implements the matching logic for one filter.
type Matcher struct {
	kind FilterKind
}

func (m Matcher) caseSensitive(q string) bool {
	switch m.kind {
	case IgnoreCase:
		return false
	case CaseSensitive:
		return true
	case SmartCase:
		return !isAllLower(q)
	case Fuzzy:
		return !isAllLower(q)
	}
	return true
}

func isAllLower(s string) bool {
	if s == "" {
		return true
	}
	for _, r := range s {
		if r >= 'A' && r <= 'Z' {
			return false
		}
	}
	return true
}

// Filter runs the query against lines, returning the matches in input order.
func (m Matcher) Filter(q string, lines []*Line) []*Match {
	terms := parseQuery(q)
	if len(terms) == 0 {
		out := make([]*Match, 0, len(lines))
		for _, l := range lines {
			out = append(out, &Match{Line: l})
		}
		return out
	}
	switch m.kind {
	case IRegexp, Regexp:
		return m.filterRegexp(terms, lines)
	}
	return m.filterSubstr(terms, lines, q)
}

func (m Matcher) filterSubstr(terms []term, lines []*Line, q string) []*Match {
	cs := m.caseSensitive(q)
	out := []*Match{}
	for _, l := range lines {
		ranges, ok := m.substrMatch(l.Display, terms, cs)
		if !ok {
			continue
		}
		out = append(out, &Match{Line: l, Ranges: ranges})
	}
	return out
}

func (m Matcher) substrMatch(s string, terms []term, cs bool) ([]int, bool) {
	var pos []string
	var neg []string
	for _, t := range terms {
		if t.neg {
			neg = append(neg, t.text)
		} else {
			pos = append(pos, t.text)
		}
	}
	var ranges []int
	for _, p := range pos {
		r := findAll(s, p, cs)
		if r == nil {
			return nil, false
		}
		ranges = append(ranges, r...)
	}
	for _, n := range neg {
		if findAll(s, n, cs) != nil {
			return nil, false
		}
	}
	return ranges, true
}

// findAll returns the ranges of all occurrences of needle in s.
func findAll(s, needle string, cs bool) []int {
	if needle == "" {
		return nil
	}
	var out []int
	if cs {
