{"command": "cd /workspace && cat > peco/view.go <<'EOF'
package peco

import (
	"fmt"
	"strings"

	"github.com/gdamore/tcell/v2"

	"peco/config"
)

// style converts a config style into a tcell style.
func style(s config.Style) tcell.Style {
	st := tcell.StyleDefault
	if s.HasFG() {
		st = st.Foreground(color(s.FG()))
	}
	if s.HasBG() {
		st = st.Background(color(s.BG()))
	}
	a := s.Attrs()
	if a&config.AttrBold != 0 {
		st = st.Bold(true)
	}
	if a&config.AttrUnderline != 0 {
		st = st.Underline(true)
	}
	if a&config.AttrReverse != 0 {
		st = st.Reverse(true)
	}
	if a&config.AttrBlink != 0 {
		st = st.Blink(true)
	}
	return st
}

func color(n int) tcell.Color {
	if n == config.ColorDefault {
		return tcell.ColorDefault
	}
	if n&0x1000000 != 0 {
		rgb := n & 0xffffff
		return tcell.NewRGBColor(int32((rgb>>16)&0xff), int32((rgb>>8)&0xff), int32(rgb&0xff))
	}
	if n < 16 {
		return tcell.ColorBlack + tcell.Color(n)
	}
	return tcell.Color16 + tcell.Color(n-16)
}

// styles holds the resolved styles used by the view.
type styles struct {
	basic          tcell.Style
	savedSelection tcell.Style
	selected       tcell.Style
	query          tcell.Style
	queryCursor    tcell.Style
	matched        tcell.Style
	prompt         tcell.Style
	context        tcell.Style
