	if !c.Style.Basic.IsZero() {
		s.basic = style(c.Style.Basic)
	}
	if !c.Style.SavedSelection.IsZero() {
		s.savedSelection = style(c.Style.SavedSelection)
	} else {
		s.savedSelection = tcell.StyleDefault.Bold(true).
			Foreground(tcell.ColorBlack).Background(color(6))
	}
	if !c.Style.Selected.IsZero() {
		s.selected = style(c.Style.Selected)
	} else {
		s.selected = tcell.StyleDefault.Underline(true).Background(color(5))
	}
	if !c.Style.Query.IsZero() {
		s.query = style(c.Style.Query)
	}
	if !c.Style.QueryCursor.IsZero() {
		s.queryCursor = style(c.Style.QueryCursor)
	} else {
		s.queryCursor = tcell.StyleDefault.Reverse(true)
	}
	if !c.Style.Matched.IsZero() {
		s.matched = style(c.Style.Matched)
	} else {
		s.matched = tcell.StyleDefault.Foreground(color(6))
	}
	if !c.Style.Prompt.IsZero() {
		s.prompt = style(c.Style.Prompt)
	}
	if !c.Style.Context.IsZero() {
		s.context = style(c.Style.Context)
	} else {
		s.context = tcell.StyleDefault.Bold(true)
	}
	// The status message is the basic style plus bold and reverse.
	m := s.basic
	if fg, bg, _ := m.Decompose(); true {
		_ = fg
		_ = bg
	}
	_, _, at := m.Decompose()
	m = tcell.StyleDefault.Foreground(func() tcell.Color {
		fg, _, _ := s.basic.Decompose()
		return fg
	}()).Background(func() tcell.Color {
		_, bg, _ := s.basic.Decompose()
		return bg
	}())
	_ = at
	s.message = m.Bold(true).Reverse(true)
	return s
}

// layout describes where the pieces of the screen go.
type layout struct {
	// queryRow is the row (0 based) holding the query prompt.
	queryRow int
	// resultRows is the number of rows available for the list.
	resultRows int
	// resultTop is the first row (0 based) of the result list.
	resultTop int
	// bottomUp inverts the order the list is drawn in.
	bottomUp bool
	// statusRow is the row holding the status message.
	statusRow int
}

func computeLayout(c *config.Config, rows, height int) layout {
	l := layout{}
	total := rows
	if height > 0 {
		total = height + 2
	}
	l.statusRow = rows - 1
	switch c.Layout {
	case "bottom-up":
		l.bottomUp = true
		l.queryRow = rows - 2
		l.resultRows = rows - 2
		l.resultTop = 0
	case "top-down-query-bottom":
		l.queryRow = rows - 2
		l.resultRows = rows - 2
		l.resultTop = 0
	default:
		l.queryRow = 0
		l.resultRows = rows - 2
		l.resultTop = 1
	}
	if height > 0 {
		l.resultRows = height
		l.queryRow = rows - total
		l.resultTop = l.queryRow + 1
		if l.bottomUp || c.Layout == "top-down-query-bottom" {
			l.resultRows = height
			l.queryRow = rows - total
			l.resultTop = l.queryRow + 1
		}
	}
	return l
}

// view draws the UI.
type view struct {
	scr    tcell.Screen
	st     *styles
	cfg    *config.Config
	lay    layout
	cols   int
	rows   int
	scroll int
}

func newView(scr tcell.Screen, cfg *config.Config, rows, height int) *view {
	v := &view{scr: scr, st: newStyles(cfg), cfg: cfg, rows: rows}
	v.resize(cfg, rows, height)
	return v
}

func (v *view) resize(cfg *config.Config, rows, height int) {
	w, h := v.scr.Size()
	v.cols = w
	v.rows = h
	v.lay = computeLayout(cfg, h, height)
}

// drawQuery renders the query line.
func (v *view) drawQuery(s *session) {
	y := v.lay.queryRow
	width := v.cols
	// the right hand side: the filter name and the match count
	right := fmt.Sprintf("%s [%d (%d/%d)]", FilterName(s.filterKind), s.matchCount,
		s.page()+1, s.pageCount())
	rcol := width - len(right)
	if rcol < 0 {
		rcol = 0
	}
	// fill the row with the query style
	for x := 0; x < width; x++ {
		v.scr.SetContent(x, y, ' ', v.st.query)
	}
	// prompt
	x := 0
	for _, r := range s.prompt {
		if x >= rcol && rcol > 0 {
			break
		}
		v.scr.SetContent(x, y, r, v.st.prompt)
		x++
	}
	// query text with the caret
	caretCol := -1
	i := 0
	for _, r := range []rune(s.query.text) {
		if i == s.query.caret {
			caretCol = x
		}
		if x >= rcol && rcol > 0 {
			break
		}
		v.scr.SetContent(x, y, r, v.st.query)
		x++
		i++
	}
	if s.query.caret >= len([]rune(s.query.text)) {
		caretCol = x
	}
	if caretCol < 0 {
		caretCol = x
	}
	// the caret cell
	if x < rcol || rcol == 0 {
		if x < width {
			v.scr.SetContent(x, y, ' ', v.st.queryCursor)
		}
		x++
	}
	// the right hand side
	if rcol > 0 {
		for i, r := range []rune(right) {
			if rcol+i >= width {
				break
			}
			v.scr.SetContent(rcol+i, y, r, v.st.basic)
		}
	}
	v.setCursor(s, caretCol, y)
}

func (v *view) setCursor(s *session, x, y int) {
	v.scr.ShowCursor(x, y)
}

// lineStyle picks the base style for a result line.
func (v *view) lineStyle(s *session, idx int) tcell.Style {
	if s.cursor == idx {
		return v.st.selected
	}
	if s.selection.has(s.resultLineId(idx)) {
		return v.st.savedSelection
	}
	return v.st.basic
}

func mergeMatched(base tcell.Style, m tcell.Style) tcell.Style {
	fg, _, _ := m.Decompose()
	_, bg, _ := base.Decompose()
	_, _, attrs := m.Decompose()
	st := tcell.StyleDefault.Foreground(fg)
	if bg != tcell.ColorDefault {
		st = st.Background(bg)
	}
	if attrs&tcell.AttrBold != 0 {
		st = st.Bold(true)
	}
	if attrs&tcell.AttrUnderline != 0 {
		st = st.Underline(true)
	}
	if attrs&tcell.AttrReverse != 0 {
		st = st.Reverse(true)
	}
	if attrs&tcell.AttrBlink != 0 {
		st = st.Blink(true)
	}
	return st
}

// drawResults renders the visible portion of the result list.
func (v *view) drawResults(s *session) {
	rows := v.lay.resultRows
	for i := 0; i < rows; i++ {
		y := v.lay.resultTop + i
		if v.lay.bottomUp {
			y = v.lay.resultTop + rows - 1 - i
		}
		idx := s.top + i
		for x := 0; x < v.cols; x++ {
			v.scr.SetContent(x, y, ' ', v.st.basic)
		}
		if idx >= len(s.results) {
			continue
		}
		m := s.results[idx]
		base := v.lineStyle(s, idx)
		v.drawLine(y, m, base, s)
	}
}

func (v *view) drawLine(y int, m *Match, base tcell.Style, s *session) {
	text := []rune(m.Line.Display)
	off := v.scroll
	// the selection prefix occupies the leftmost columns
	prefix := ""
	if s.cfg.SelectionPrefix != "" {
		if s.selection.has(s.resultLineIdIdx(idx)) {
			prefix = s.cfg.SelectionPrefix
		}
	}
	_ = prefix
	x := 0
	hi := m.Ranges
	for i := 0; i < len(text); i++ {
		if x >= v.cols {
			break
		}
		cx := i - off
		if cx < 0 {
			continue
		}
		st := base
		for j := 0; j+1 < len(hi); j += 2 {
			if i >= hi[j] && i < hi[j+1] {
				st = mergeMatched(base, v.st.matched)
				break
			}
		}
		v.scr.SetContent(cx, y, text[i], st)
		x++
	}
}

func (v *view) drawStatus(s *session) {
	y := v.lay.statusRow
	width := v.cols
	msg := s.status
	if v.cfg.SuppressStatusMsg {
		msg = ""
	}
	pad := width - len(msg)
	if pad < 0 {
		pad = 0
		r := []rune(msg)
		msg = string(r[len(r)-width:])
	}
	for x := 0; x < width; x++ {
		v.scr.SetContent(x, y, ' ', v.st.basic)
	}
	col := width - len(msg)
	if col < 0 {
		col = 0
	}
	for i, r := range []rune(msg) {
		if col+i >= width {
			break
		}
		v.scr.SetContent(col+i, y, r, v.st.message)
	}
}

func (v *view) show() { v.scr.Show() }

