// selection holds the lines the user has marked.
type selection struct {
	set  map[int]struct{}
	list []int
}

func newSelection() *selection {
	return &selection{set: map[int]struct{}{}}
}

func (s *selection) has(id int) bool {
	_, ok := s.set[id]
	return ok
}

func (s *selection) add(id int) {
	if _, ok := s.set[id]; ok {
		return
	}
	s.set[id] = struct{}{}
	s.list = append(s.list, id)
}

func (s *selection) remove(id int) {
	if _, ok := s.set[id]; !ok {
		return
	}
	delete(s.set, id)
	for i, v := range s.list {
		if v == id {
			s.list = append(s.list[:i], s.list[i+1:]...)
			break
		}
	}
}

func (s *selection) toggle(id int) {
	if s.has(id) {
		s.remove(id)
		return
	}
	s.add(id)
}

func (s *selection) clear() {
	s.set = map[int]struct{}{}
	s.list = nil
}

func (s *selection) size() int { return len(s.list) }

func (s *selection) sorted() []int {
	out := make([]int, len(s.list))
	copy(out, s.list)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j] < out[j-1]; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

// query is the editable query text.
type query struct {
	text  string
	caret int
}

func (q *query) runes() []rune { return []rune(q.text) }

func (q *query) insert(r rune) {
	rs := q.runes()
	c := q.caret
	if c > len(rs) {
		c = len(rs)
	}
	rs = append(rs[:c], append([]rune{r}, rs[c:]...)...)
	q.text = string(rs)
	q.caret = c + 1
}

func (q *query) deleteBackward() {
	rs := q.runes()
	if q.caret == 0 {
		return
	}
	q.text = string(rs[:q.caret-1]) + string(rs[q.caret:])
	q.caret--
}

func (q *query) deleteForward() {
	rs := q.runes()
	if q.caret >= len(rs) {
		return
	}
	q.text = string(rs[:q.caret]) + string(rs[q.caret+1:])
}

// session holds the whole interactive state.
type session struct {
	cfg        *config.Config
	scr        tcell.Screen
	view       *view
	buf        *Buffer
	prompt     string
	query      query
	filterKind FilterKind
	filterIdx  int
	filterList []FilterKind
	custom     map[string]*customFilter
	results    []*Match
	matchCount int
	cursor     int
	top        int
	sel        *selection
	status     string
	height     int
	pageSize   int
	// pending key sequence
	pendingSeq []string
	pendingKey string
	// bookkeeping
	inputDone bool
	quitting  bool
	cancelled bool
	out       []string
	printQuery bool
	null       bool
	// for the filter
	scrollOffset int
	zoomed       bool
	rangeMode    bool
	rangeStart   int
	selectMode   bool
	jumpMode     bool
	sticky       bool
	initialFilter FilterKind
	// channels
	keyCh     chan *tcell.EventKey
	bufCh     chan struct{}
	doneCh    chan struct{}
	filterCh  chan string
	queryCh   chan struct{}
	inputEnd  chan struct{}
}

type customFilter struct {
	name string
	cfg  config.CustomFilterConfig
}

// newSession wires everything together.
func newSession(cfg *config.Config, scr tcell.Screen, rows, height int) *session {
	s := &session{
		cfg:      cfg,
		scr:      scr,
		buf:      NewBuffer(),
		prompt:   cfg.Prompt,
		sel:      newSelection(),
		height:   height,
		keyCh:    make(chan *tcell.EventKey, 256),
		bufCh:    make(chan struct{}, 8),
		doneCh:   make(chan struct{}),
		queryCh:  make(chan struct{}, 8),
		inputEnd: make(chan struct{}),
	}
	s.view = newView(scr, cfg, rows, height)
	s.filterList = []FilterKind{IgnoreCase, CaseSensitive, SmartCase, IRegexp, Regexp, Fuzzy}
	s.filterIdx = 0
	s.filterKind = IgnoreCase
	s.initialFilter = IgnoreCase
	s.sticky = cfg.StickySelection
	return s
}

func (s *session) pageSizeRows() int {
	if s.height > 0 {
		return s.height
	}
	return s.view.lay.resultRows
}

func (s *session) page() int {
	pz := s.pageSizeRows()
	if pz <= 0 {
		return 0
	}
	return s.cursor / pz
}

func (s *session) pageCount() int {
	pz := s.pageSizeRows()
	if pz <= 0 {
		return 1
	}
	n := len(s.results)
	if n == 0 {
		return 1
	}
	return (n + pz - 1) / pz
}

// setFilter switches to the given filter and re-runs the query.
func (s *session) setFilter(k FilterKind) {
	s.filterKind = k
	for i, f := range s.filterList {
		if f == k {
			s.filterIdx = i
			break
		}
	}
}

// runFilter filters the buffer with the current query.
func (s *session) runFilter() {
	if s.filterKind == Fuzzy {
		m := Matcher{kind: Fuzzy}
		s.results = m.filterFuzzy(s.query.text, s.buf.Lines())
	} else {
		m := Matcher{kind: s.filterKind}
		s.results = m.Filter(s.query.text, s.buf.Lines())
	}
	s.matchCount = len(s.results)
	if s.cursor >= len(s.results) {
		s.cursor = 0
		if len(s.results) > 0 {
			s.cursor = len(s.results) - 1
		}
	}
	s.top = 0
	if s.cursor >= s.pageSizeRows() {
		s.top = s.cursor - s.pageSizeRows() + 1
	}
}

// drawAll draws everything.
func (s *session) drawAll() {
	s.view.drawQuery(s)
	s.view.show()
	s.view.drawResults(s)
	s.view.show()
	s.view.drawStatus(s)
	s.view.show()
}

func (s *session) setStatus(msg string) {
	s.status = msg
	s.view.drawStatus(s)
	s.view.show()
}

func (s *session) clearStatus() { s.setStatus("") }

func (s *session) redraw() {
	s.view.drawQuery(s)
	s.view.show()
	s.view.drawResults(s)
	s.view.show()
}

// filterRun applies the query, redrawing as the original does.
func (s *session) filterRun() {
	s.setStatus("Running query...")
	s.matchCount = 0
	s.view.drawQuery(s)
	s.view.show()
	s.runFilter()
	s.view.drawResults(s)
	s.view.show()
	s.view.drawQuery(s)
	s.view.show()
	s.clearStatus()
}
