		fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to apply configuration: %s\n", err.Error())
		return 1
	}

	// input source
	var in io.Reader
	if len(args) > 0 {
		fp, err := os.Open(args[0])
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: failed to setup input source: failed to open file for input: %s\n", err.Error())
			return 1
		}
		in = fp
	} else {
		fi, err := os.Stdin.Stat()
		if err == nil && fi.Mode()&os.ModeCharDevice != 0 && fi.Mode()&os.ModeNamedPipe == 0 {
			// a tty: nothing to read
			fmt.Fprintf(os.Stderr, "Error: failed to setup input source: you must supply something to work with via filename or stdin\n")
			return 1
		}
		in = os.Stdin
	}

	return runInteractive(cfg, in, query, height, select1, exit0, selectAll, printQuery, null, execCmd, initialIndex)
}

func boolPtr(b *bool) *string { return nil }

func hasFlag(opts []*option.Option, name string, args []string) bool {
	for _, a := range args {
		if a == name {
			return true
		}
		if strings.HasPrefix(a, name+"=") {
			return true
		}
	}
	return false
}

func applyConfig(cfg *config.Config, height, oncancel, initialFilter, prompt, selectionPrefix string, ansi bool, args []string, bufferSize, initialIndex int) error {
	if height != "" {
		if err := parseHeight(cfg, height); err != nil {
			return fmt.Errorf("failed to parse height specification: %s", err.Error())
		}
		cfg.Height = height
	}
	if oncancel != "" {
		switch oncancel {
		case "success":
			cfg.OnCancel = config.OnCancelSuccess
		case "error":
			cfg.OnCancel = config.OnCancelError
		default:
			return fmt.Errorf("invalid --on-cancel value: invalid OnCancel value %q: must be \"success\" or \"error\"", oncancel)
		}
	}
	if initialFilter != "" {
		if _, ok := peco.FilterFromName(initialFilter); !ok {
			return fmt.Errorf("failed to populate initial filter: failed to set filter: specified filter was not found")
		}
		cfg.InitialFilter = initialFilter
	}
	if prompt != "" {
		cfg.Prompt = prompt
	}
	if selectionPrefix != "" {
		cfg.SelectionPrefix = selectionPrefix
	}
	if ansi {
		cfg.ANSI = true
	}
	return nil
}

func parseHeight(cfg *config.Config, spec string) error {
	if strings.HasSuffix(spec, "%") {
		pct, err := strconv.Atoi(strings.TrimSuffix(spec, "%"))
		if err != nil {
			return fmt.Errorf("invalid height specification: %q", spec)
		}
		return nil
	}
	n, err := strconv.Atoi(spec)
	if err != nil {
		return fmt.Errorf("invalid height specification: %q", spec)
	}
	if n <= 0 {
		return fmt.Errorf("height must be positive: %q", spec)
	}
	return nil
}

func runInteractive(cfg *config.Config, in io.Reader, query, height string, select1, exit0, selectAll, printQuery, null bool, execCmd string, initialIndex int) int {
	events := make(chan event, 512)

	// read the input
	go func() {
		br := bufio.NewReaderSize(in, 256*1024)
		pending := ""
		for {
			chunk := make([]byte, 65536)
			n, err := br.Read(chunk)
			if n > 0 {
				data := pending + string(chunk[:n])
				lines, rest := peco.SplitLines(data)
				pending = rest
				if len(lines) > 0 {
					events <- event{kind: evLines, keys: nil}
					_ = lines
				}
			}
			if err != nil {
				break
			}
		}
		events <- event{kind: evEOF}
	}()

	screenReady := false
	var scr tcell.Screen
	var sess *peco.Session
	var heightRows int
	if height != "" {
		heightRows = peco.ParseHeight(height, 24)
	}

	for {
		ev := <-events
		switch ev.kind {
		case evEOF:
			if selectAll {
				return 0
			}
			if exit0 {
				return 1
			}
			if select1 {
				return 0
			}
			if !screenReady {
				s, err := initScreen(cfg, heightRows)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: %s\n", err.Error())
					return 1
				}
				scr = s
				screenReady = true
			}
			sess = peco.NewSession(cfg, scr, query, heightRows)
			sess.Run(events)
			return 0
		case evLines:
			if !screenReady {
				s, err := initScreen(cfg, heightRows)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: failed to initialize screen: %s\n", err.Error())
					return 1
				}
				scr = s
				screenReady = true
				sess = peco.NewSession(cfg, scr, query, heightRows)
				sess.Run(events)
				return 0
			}
		}
	}
}

func initScreen(cfg *config.Config, heightRows int) (tcell.Screen, error) {
	scr, err := tcell.NewScreen()
	if err != nil {
		return nil, fmt.Errorf("failed to create tcell screen: %s", err.Error())
	}
	if err := scr.Init(); err != nil {
		return nil, fmt.Errorf("failed to initialize tcell screen: %s", err.Error())
	}
	return scr, nil
}
