{"command": "cd /workspace && cat > peco/session.go <<'EOF'
package peco

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"

	"github.com/gdamore/tcell/v2"

	"peco/config"
)

// Options carries the command line settings that influence the interactive
// session.
type Options struct {
	Query        string
	Height       string
	Select1      bool
	Exit0        bool
	SelectAll    bool
	PrintQuery   bool
	Null         bool
	ExecCmd      string
	InitialIndex int
}

// eventKind enumerates the messages the main loop understands.
type eventKind int

const (
	evKey eventKind = iota
	evLines
	evEOF
	evResize
	evStatus
)

type event struct {
	kind eventKind
	key  *tcell.EventKey
}

// Session is the whole interactive state of one peco run.
type Session struct {
	cfg     *config.Config
	opts    Options
	scr     tcell.Screen
	v       *view
	buf     *Buffer
	prompt  string
	q       query
	kind    FilterKind
	idx     int
	filters []FilterKind
	custom  map[string]*customFilter
	results []*Match
	count   int
	cursor  int
	top     int
	sel     *selection
	status  string
	sticky  bool

	keymap     map[string][]action
	seqKeys    map[string]bool
	pendingSeq string
	pendingMsg bool

	// runtime flags
	inputDone  bool
	filterRan  bool
	quitting   bool
	cancelled  bool
	zoomed     bool
	rangeMode  bool
	rangeStart int
	jump       bool
	jumpPrefix bool
	scrollX    int
	// frozen state
	frozen     bool
	frozenRes  []*Match
	frozenSel  *selection
	frozenTop  int
	frozenCur  int

	mu       sync.Mutex
	events   chan event
	HeightRows int
}

type customFilter struct {
	name string
	cfg  config.CustomFilterConfig
}

// NewSession builds the session state.
func NewSession(cfg *config.Config, opts Options) *Session {
	s := &Session{
		cfg:     cfg,
		opts:    opts,
		buf:     NewBuffer(),
		prompt:  cfg.Prompt,
		sel:     newSelection(),
		sticky:  cfg.StickySelection,
		filters: []FilterKind{IgnoreCase, CaseSensitive, SmartCase, IRegexp, Regexp, Fuzzy},
		events:  make(chan event, 1024),
	}
	s.kind = IgnoreCase
	if k, ok := FilterFromName(cfg.InitialFilter); ok {
		s.kind = k
	}
	s.keymap = map[string][]action{}
	for k, v := range defaultKeymap() {
		s.keymap[k] = []action{v}
	}
	s.seqKeys = map[string]bool{}
	for k := range s.keymap {
		if strings.Contains(k, ",") {
			s.seqKeys[strings.SplitN(k, ",", 2)[0]] = true
		}
	}
	// user bindings
	for key, val := range cfg.Keymap {
		acts, err := resolveAction(val, cfg.Action, 0)
		if err != nil {
			continue
		}
		s.keymap[key] = acts
		if strings.Contains(key, ",") {
			s.seqKeys[strings.SplitN(key, ",", 2)[0]] = true
		}
	}
	// custom filters participate in the rotation
	for name := range cfg.CustomFilter {
		s.custom = map[string]*customFilter{}
		break
	}
	if s.custom == nil {
		s.custom = map[string]*customFilter{}
	}
	for name, c := range cfg.CustomFilter {
		s.custom[name] = &customFilter{name: name, cfg: c}
	}
	s.q.text = opts.Query
	return s
}

// SetScreen attaches the tcell screen and builds the view.
func (s *Session) SetScreen(scr tcell.Screen) {
	s.scr = scr
	hr := ParseHeight(s.opts.Height, scr.Size())
	s.v = newView(scr, s.cfg, hr)
	s.cursor = s.opts.InitialIndex
	if s.cursor > 0 && s.cursor < len(s.results) {
		// keep
	}
}

// Run drives the event loop until the user finishes or cancels.
func (s *Session) Run() int {
	if s.scr == nil {
		return 1
	}
	s.v.resize()
	// initial draw of the list
	s.results = s.buf.Lines()
	s.count = len(s.results)
	s.v.drawQuery(s)
	s.v.show()
	s.v.drawResults(s)
	s.v.show()
	s.v.drawStatus(s)
	s.v.show()

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()

	for {
		var ev event
		select {
		case ev = <-s.events:
		case <-ticker.C:
			if !s.inputDone {
				s.v.drawQuery(s)
				s.v.show()
				s.v.drawStatus(s)
				s.v.show()
			}
			continue
		}
		switch ev.kind {
		case evKey:
			if s.handleKey(ev.key) {
				return s.exitCode()
			}
		case evLines:
			s.mu.Lock()
			n := s.buf.Length()
			s.mu.Unlock()
			s.onLines(n)
		case evEOF:
			s.inputDone = true
			if s.handleEOF() {
				return s.exitCode()
			}
		case evResize:
			s.v.resize()
			s.redraw()
		case evStatus:
			s.v.drawStatus(s)
			s.v.show()
		}
	}
}

func (s *Session) exitCode() int {
	if s.cancelled {
		if s.cfg.OnCancel == config.OnCancelError {
			return 1
		}
		return 0
	}
	return 0
}

func (s *Session) onLines(n int) {
	s.mu.Lock()
	lines := s.buf.Lines()
	s.mu.Unlock()
	if s.q.text == "" && !s.filterRan {
		s.results = lines
		s.count = len(lines)
		if s.cursor >= len(s.results) {
			s.cursor = len(s.results) - 1
			if s.cursor < 0 {
				s.cursor = 0
			}
		}
	} else {
		s.filterRun()
	}
	s.v.drawQuery(s)
	s.v.show()
	s.v.drawResults(s)
	s.v.show()
	s.v.drawStatus(s)
	s.v.show()
}

// handleEOF deals with the end of the input and the immediate exit options.
func (s *Session) handleEOF() bool {
	if s.opts.SelectAll {
		for i := range s.buf.Lines() {
			s.sel.add(i)
		}
		s.finish()
		return true
	}
	if s.opts.Exit0 && s.buf.Length() == 0 {
		s.quitting = true
		return true
	}
	if s.opts.Select1 && s.buf.Length() == 1 {
		s.cursor = 0
		s.finish()
		return true
	}
	s.status = ""
	s.v.drawStatus(s)
	s.v.show()
	if s.q.text != "" && !s.filterRan {
		s.filterRun()
	} else {
		s.v.drawQuery(s)
		s.v.show()
		s.v.drawResults(s)
		s.v.show()
	}
	return false
}

// filterRun re-runs the query and redraws.
func (s *Session) filterRun() {
	s.setStatusMsg("Running query...")
	s.count = 0
	s.v.drawQuery(s)
	s.v.show()
	s.runFilter()
	s.v.drawResults(s)
	s.v.show()
	s.v.drawQuery(s)
	s.v.show()
	s.status = ""
	s.v.drawStatus(s)
	s.v.show()
}

func (s *Session) setStatusMsg(msg string) {
	s.status = msg
	s.v.drawStatus(s)
	s.v.show()
}

func (s *Session) runFilter() {
	if s.kind == Fuzzy {
		m := Matcher{kind: Fuzzy}
		s.results = m.filterFuzzy(s.q.text, s.buf.Lines())
	} else {
		m := Matcher{kind: s.kind}
		s.results = m.Filter(s.q.text, s.buf.Lines())
	}
	s.count = len(s.results)
	s.cursor = 0
	s.top = 0
	s.sel.clear()
}

func (s *session_unused_guard) nop() {}

func (s *Session) redraw() {
	s.v.drawQuery(s)
	s.v.show()
	s.v.drawResults(s)
	s.v.show()
	s.v.drawStatus(s)
	s.v.show()
}

// AddLines appends lines read from the input.
func (s *Session) AddLines(lines []*Line) {
	s.mu.Lock()
	s.buf.Add(lines)
	s.mu.Unlock()
	s.events <- event{kind: evLines}
}

// PostKey posts a key event.
func (s *Session) PostKey(ev *tcell.EventKey) { s.events <- event{kind: evKey, key: ev} }

// PostEOF signals the end of the input.
func (s *Session) PostEOF() { s.events <- event{kind: evEOF} }

// PostStatus asks for a status line redraw.
func (s *Session) PostStatus() { s.events <- event{kind: evStatus} }

// PostResize signals a terminal resize.
func (s *Session) PostResize() { s.events <- event{kind: evResize} }

// output returns the lines to print when finishing.
func (s *Session) output() []string {
	var ids []int
	if s.sel.size() > 0 {
		ids = s.sel.sorted()
	} else if s.cursor >= 0 && s.cursor < len(s.results) {
		ids = []int{s.results[s.cursor].Line.id}
	}
	out := []string{}
	for _, id := range ids {
		l := s.buf.At(id)
		if l == nil {
			continue
		}
		if s.opts.Null {
			if i := strings.IndexByte(l.Raw, 0); i >= 0 {
				out = append(out, l.Raw[i+1:])
				continue
			}
		}
		out = append(out, l.Raw)
	}
	return out
}

func (s *Session) finish() {
	s.quitting = true
}

// Finish writes the selection to stdout.
func (s *Session) Finish() {
	if s.opts.PrintQuery {
		fmt.Fprintln(os.Stdout, s.q.text)
	}
	for _, l := range s.output() {
		fmt.Fprintln(os.Stdout, l)
	}
	if s.opts.ExecCmd != "" {
		s.execCommand()
	}
}

func (s *Session) execCommand() {
	lines := s.output()
	cmd := exec.Command("/bin/sh", "-c", s.opts.ExecCmd)
	cmd.Stdin = strings.NewReader(strings.Join(lines, "\n") + "\n")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
}

var _ = io.Discard
var _ = fmt.Sprintf
EOF
