package peco

// query holds the editable query text and the caret position.
type query struct {
	text  string
	caret int
}

func (q *query) runes() []rune { return []rune(q.text) }

func (q *query) insert(r rune) {
	rs := q.runes()
	c := q.caret
	if c > len(rs) {
		c = len(rs)
	}
	out := make([]rune, 0, len(rs)+1)
	out = append(out, rs[:c]...)
	out = append(out, r)
	out = append(out, rs[c:]...)
	q.text = string(out)
	q.caret = c + 1
}

func (q *query) deleteBackward() {
	rs := q.runes()
	if q.caret == 0 {
		return
	}
	out := make([]rune, 0, len(rs))
	out = append(out, rs[:q.caret-1]...)
	out = append(out, rs[q.caret:]...)
	q.text = string(out)
	q.caret--
}

func (q *query) deleteForward() {
	rs := q.runes()
	if q.caret >= len(rs) {
		return
	}
	out := make([]rune, 0, len(rs))
	out = append(out, rs[:q.caret]...)
	out = append(out, rs[q.caret+1:]...)
	q.text = string(out)
}
