package peco

// selection holds the lines the user has marked.
type selection struct {
	set  map[int]struct{}
	list []int
}

func newSelection() *selection {
	return &selection{set: map[int]struct{}{}}
}

func (s *selection) has(id int) bool {
	_, ok := s.set[id]
	return ok
}

func (s *selection) add(id int) {
	if _, ok := s.set[id]; ok {
		return
	}
	s.set[id] = struct{}{}
	s.list = append(s.list, id)
}

func (s *selection) remove(id int) {
	if _, ok := s.set[id]; !ok {
		return
	}
	delete(s.set, id)
	for i, v := range s.list {
		if v == id {
			s.list = append(s.list[:i], s.list[i+1:]...)
			break
		}
	}
}

func (s *selection) toggle(id int) {
	if s.has(id) {
		s.remove(id)
		return
	}
	s.add(id)
}

func (s *selection) clear() {
	s.set = map[int]struct{}{}
	s.list = nil
}

func (s *selection) size() int { return len(s.list) }

func (s *selection) sorted() []int {
