// ParseHeight converts a height specification ("10" or "50%") into the number
// of result rows for the given terminal height.  A value of 0 means "use the
// whole terminal".
func ParseHeight(spec string, rows int) int {
	if spec == "" {
		return 0
	}
	if strings.HasSuffix(spec, "%") {
		pct, err := strconv.Atoi(strings.TrimSuffix(spec, "%"))
		if err != nil || pct <= 0 {
			return 0
		}
		total := rows * pct / 100
		if total < 3 {
			total = 3
		}
		if total > rows {
			total = rows
		}
		return total - 2
	}
	n, err := strconv.Atoi(spec)
	if err != nil || n <= 0 {
		return 0
	}
	return n
}

// SplitLines splits a chunk of input into complete lines, returning the
// trailing partial line separately.
func SplitLines(data string) ([]string, string) {
	var lines []string
	for {
		i := strings.IndexByte(data, '\n')
		if i < 0 {
			break
		}
		l := data[:i]
		l = strings.TrimSuffix(l, "\r")
		lines = append(lines, l)
		data = data[i+1:]
	}
	return lines, data
}
EOF
