// handleKey processes one key event.  It returns true when the session should
// end.
func (s *Session) handleKey(ev *tcell.EventKey) bool {
	name := keyName(ev)
	disp := keyDisplay(ev)

	// continue a pending key sequence
	if s.pendingSeq != "" {
		full := s.pendingSeq + "," + name
		if acts, ok := s.keymap[full]; ok {
