			return s.quitting
		}
		if s.seqKeys[full] {
			s.pendingSeq = full
			s.echo(disp)
			return s.quitting
		}
		// the pending key is a plain binding: run it, then this one
		acts := s.keymap[s.pendingSeq]
		s.pendingSeq = ""
		s.pendingMsg = false
		if len(acts) > 0 {
			s.echo(keyDisplayNameFor(s.pendingSeq))
			s.runActions(acts)
		}
	}

	if acts, ok := s.keymap[name]; ok {
		if s.seqKeys[name] {
			s.pendingSeq = name
			s.echo(disp)
			return s.quitting
		}
		s.echo(disp)
		s.runActions(acts)
		s.clearEcho()
		return s.quitting
	}

	// unbound key
	if ev.Key() == tcell.KeyRune {
		s.echo(disp)
		s.q.insert(ev.Rune())
		s.queryChanged()
		s.clearEcho()
		return s.quitting
	}
	s.echo(disp)
	s.clearEcho()
	return s.quitting
}

func keyDisplayNameFor(name string) string { return name }

