	if s.pendingMsg {
		return
	}
	s.status = disp
	s.v.drawStatus(s)
	s.v.show()
}

func (s *Session) clearEcho() {
	s.status = ""
	s.v.drawStatus(s)
	s.v.show()
}

// queryChanged applies the new query text.
func (s *Session) queryChanged() {
	if !s.sticky {
		s.sel.clear()
	}
	s.filterRun()
}

// runActions executes a list of actions in order.
func (s *Session) runActions(acts []action) {
	for _, a := range acts {
		if s.quitting {
			return
		}
		s.runAction(a)
	}
}

func (s *Session) runAction(a action) {
	switch a {
	case actForwardChar:
		if s.q.caret < len(s.q.runes()) {
			s.q.caret++
			s.v.drawQuery(s)
			s.v.show()
		}
	case actBackwardChar:
		if s.q.caret > 0 {
			s.q.caret--
			s.v.drawQuery(s)
			s.v.show()
		}
	case actBeginningOfLine:
		s.q.caret = 0
		s.v.drawQuery(s)
		s.v.show()
	case actEndOfLine:
		s.q.caret = len(s.q.runes())
		s.v.drawQuery(s)
		s.v.show()
	case actForwardWord:
		s.forwardWord()
	case actBackwardWord:
		s.backwardWord()
	case actDeleteForwardChar:
		if s.q.caret < len(s.q.runes()) {
			s.q.deleteForward()
			s.queryChanged()
		}
	case actDeleteBackwardChar:
		if s.q.caret > 0 {
			s.q.deleteBackward()
			s.queryChanged()
		}
	case actDeleteForwardWord:
		s.deleteForwardWord()
	case actDeleteBackwardWord:
		s.deleteBackwardWord()
	case actKillBeginningOfLine:
		if s.q.caret > 0 {
			s.q.text = string(s.q.runes()[s.q.caret:])
			s.q.caret = 0
			s.queryChanged()
		}
	case actKillEndOfLine:
		if s.q.caret < len(s.q.runes()) {
			s.q.text = string(s.q.runes()[:s.q.caret])
			s.queryChanged()
		}
	case actDeleteAll:
		s.q.text = ""
		s.q.caret = 0
		s.queryChanged()
	case actEndOfFile:
		if s.q.caret >= len(s.q.runes()) {
			s.cancel()
			return
		}
		s.q.deleteForward()
		s.queryChanged()
	case actSelectUp:
		s.moveCursor(-1)
	case actSelectDown:
		s.moveCursor(1)
	case actSelectPrevious:
		s.moveCursor(-1)
	case actSelectNext:
		s.moveCursor(1)
	case actScrollPageUp:
		s.moveCursor(-s.pageSize())
	case actScrollPageDown:
		s.moveCursor(s.pageSize())
	case actSelectPreviousPage:
		s.moveCursor(-s.pageSize())
	case actSelectNextPage:
		s.moveCursor(s.pageSize())
	case actScrollFirstItem:
