		s.scrollX -= 10
		if s.scrollX < 0 {
			s.scrollX = 0
		}
		s.v.scroll = s.scrollX
		s.redraw()
	case actScrollRight:
		s.scrollX += 10
		s.v.scroll = s.scrollX
