	case actToggleSelection:
		if s.cursor >= 0 && s.cursor < len(s.results) {
			s.sel.toggle(s.results[s.cursor].Line.id)
		}
		s.redraw()
	case actToggleSelectionAndSelectNext:
		if s.cursor >= 0 && s.cursor < len(s.results) {
			s.sel.toggle(s.results[s.cursor].Line.id)
		}
		s.moveCursor(1)
	case actSelectAll:
		for i := range s.buf.Lines() {
			s.sel.add(i)
		}
		s.redraw()
	case actSelectVisible:
		pz := s.pageSize()
		for i := s.top; i < s.top+pz && i < len(s.results); i++ {
			s.sel.add(s.results[i].Line.id)
