	case actInvertSelection:
		var ids []int
		for i := range s.buf.Lines() {
			ids = append(ids, i)
		}
		n := newSelection()
		for _, id := range ids {
			if !s.sel.has(id) {
				n.add(id)
			}
		}
		s.sel = n
		s.redraw()
	case actGoToNextSelection:
		s.goToSelection(1)
	case actGoToPreviousSelection:
		s.goToSelection(-1)
	case actRotateFilter:
		s.rotateFilter()
	case actToggleQuery:
		s.toggleQuery()
	case actRefreshScreen:
		s.redraw()
	case actBackToInitialFilter:
		if k, ok := FilterFromName(s.cfg.InitialFilter); ok {
			s.setFilterKind(k)
			s.filterRun()
		}
	case actFinish:
		s.finish()
		return
	case actCancel:
		s.cancel()
		return
	case actViewAround, actZoomIn:
		s.zoomIn()
	case actZoomOut:
		s.zoomOut()
