}

func (s *Session) cancel() {
	s.cancelled = true
	s.quitting = true
}

func (s *Session) pageSize() int {
	pz := s.v.lay.resultRows
	if pz < 1 {
		pz = 1
	}
	return pz
}

func (s *Session) page() int { return s.cursor / s.pageSize() }

func (s *Session) pageCount() int {
	n := len(s.results)
	if n == 0 {
		return 1
	}
	pz := s.pageSize()
	return (n + pz - 1) / pz
}

// moveCursor moves the selection cursor, scrolling as needed.
func (s *Session) moveCursor(delta int) {
	if len(s.results) == 0 {
		s.setCursor(0)
		return
	}
	n := s.cursor + delta
	if n < 0 {
		n = 0
	}
	if n > len(s.results)-1 {
		n = len(s.results) - 1
	}
	s.setCursor(n)
}

func (s *Session) setCursor(n int) {
	if n < 0 {
		n = 0
	}
	if n > len(s.results)-1 {
		n = len(s.results) - 1
	}
	if n < 0 {
		n = 0
	}
	s.cursor = n
	s.adjustScroll()
	s.redraw()
}

func (s *Session) adjustScroll() {
	pz := s.pageSize()
	if s.cursor < s.top {
		s.top = s.cursor
	} else if s.cursor >= s.top+pz {
		s.top = s.cursor - pz + 1
	}
	if s.top < 0 {
		s.top = 0
	}
}

func (s *Session) setFilterKind(k FilterKind) {
	s.kind = k
	for i, f := range s.filters {
		if f == k {
			s.idx = i
			break
		}
	}
}

func (s *Session) rotateFilter() {
	s.idx = (s.idx + 1) % len(s.filters)
	s.kind = s.filters[s.idx]
	s.filterRun()
}

// toggleQuery switches between the filtered list and the whole buffer.
func (s *Session) toggleQuery() {
	if s.q.text == "" {
		return
	}
	if s.filterRan {
		s.filterRan = false
		s.results = allMatches(s.buf.Lines())
		s.count = len(s.results)
		s.cursor = 0
		s.top = 0
		s.sel.clear()
		s.redraw()
		return
	}
	s.filterRan = true
	s.filterRun()
}

func (s *Session) goToSelection(dir int) {
	if s.sel.size() == 0 {
		return
	}
	ids := s.sel.sorted()
	// find the current position among the selections
	pos := -1
	for i, id := range ids {
		if s.cursor < len(s.results) && s.results[s.cursor].Line.id == id {
			pos = i
			break
		}
	}
	next := pos + dir
	if next >= len(ids) {
		next = 0
	}
	if next < 0 {
		next = len(ids) - 1
	}
	// find the result index of that id
	for i, m := range s.results {
		if m.Line.id == ids[next] {
			s.setCursor(i)
			return
		}
	}
}

func (s *Session) forwardWord() {
	rs := s.q.runes()
	i := s.q.caret
	for i < len(rs) && isWordSep(rs[i]) {
		i++
	}
	for i < len(rs) && !isWordSep(rs[i]) {
		i++
	}
	s.q.caret = i
	s.v.drawQuery(s)
	s.v.show()
}

func (s *Session) backwardWord() {
	rs := s.q.runes()
	i := s.q.caret
	for i > 0 && isWordSep(rs[i-1]) {
		i--
	}
	for i > 0 && !isWordSep(rs[i-1]) {
		i--
	}
	s.q.caret = i
	s.v.drawQuery(s)
	s.v.show()
}

func (s *Session) deleteForwardWord() {
	rs := s.q.runes()
	i := s.q.caret
	start := i
	for i < len(rs) && isWordSep(rs[i]) {
		i++
	}
	for i < len(rs) && !isWordSep(rs[i]) {
		i++
	}
	if i == start {
		return
	}
	out := make([]rune, 0, len(rs))
	out = append(out, rs[:start]...)
	out = append(out, rs[i:]...)
	s.q.text = string(out)
	s.queryChanged()
}

func (s *Session) deleteBackwardWord() {
	rs := s.q.runes()
	i := s.q.caret
	for i > 0 && isWordSep(rs[i-1]) {
		i--
	}
	for i > 0 && !isWordSep(rs[i-1]) {
		i--
	}
	if i == s.q.caret {
		return
	}
	out := make([]rune, 0, len(rs))
	out = append(out, rs[:i]...)
	out = append(out, rs[s.q.caret:]...)
	s.q.text = string(out)
	s.q.caret = i
	s.queryChanged()
}

func isWordSep(r rune) bool {
	return r == ' ' || r == '\t'
}

// zoomIn shows context lines around each match.
func (s *Session) zoomIn() {
	if s.zoomed || len(s.results) == 0 {
		s.redraw()
		return
	}
	s.zoomed = true
	included := map[int]bool{}
	var out []*Match
	for _, m := range s.results {
		id := m.Line.id
		for i := id - 3; i <= id+3; i++ {
			if i < 0 || included[i] {
				continue
			}
			l := s.buf.At(i)
			if l == nil {
				continue
			}
			included[i] = true
			mm := &Match{Line: l}
			if i == id {
				mm.Ranges = m.Ranges
			}
			out = append(out, mm)
		}
	}
	s.results = out
	s.count = len(out)
	s.cursor = 0
	s.top = 0
	s.sel.clear()
	s.redraw()
}

func (s *Session) zoomOut() {
	if !s.zoomed {
		s.redraw()
		return
	}
	s.zoomed = false
	s.filterRun()
}

func (s *Session) freeze() {
	if s.frozen {
		return
	}
	s.frozen = true
	s.frozenRes = s.results
	s.frozenSel = s.sel
	s.frozenTop = s.top
	s.frozenCur = s.cursor
	s.q.text = ""
	s.q.caret = 0
	s.count = len(s.results)
	s.cursor = 0
	s.top = 0
	s.redraw()
}

func (s *Session) unfreeze() {
	if !s.frozen {
		return
	}
	s.frozen = false
	s.results = s.frozenRes
	s.sel = s.frozenSel
	s.top = s.frozenTop
	s.cursor = s.frozenCur
	s.count = len(s.results)
	s.redraw()
}

