	if !ready {
		return
	}
	if code == 0 && !s.cancelled {
		s.Finish()
	}
	scr.Fini()
}

func makeLines(lines []string, null bool) []*Line {
	out := make([]*Line, 0, len(lines))
	for _, l := range lines {
		if null {
			parts := strings.SplitN(l, "\x00", 2)
			if len(parts) == 2 {
				out = append(out, &Line{Display: parts[0], Raw: l})
				continue
			}
		}
		out = append(out, &Line{Display: l, Raw: l})
	}
	return out
}

func splitNull(data string) ([]string, string) {
	var out []string
	for {
		i := strings.IndexByte(data, '\n')
		if i < 0 {
			break
		}
		l := data[:i]
		l = strings.TrimSuffix(l, "\r")
		out = append(out, l)
		data = data[i+1:]
	}
	return out, data
}

