import sys, os, subprocess, time, select, fcntl, termios, struct, pty, signal
sys.path.insert(0,'/tmp/h')
import ansi, keys as K
BIN=os.environ.get('BIN','/workspace/executable')
def ptyrun(cmd, keys=(), cols=80, rows=24, delay=0.35, timeout=2.0, env=None):
    e=dict(os.environ); e['TERM']='xterm-256color'
    if env: e.update(env)
    pid, fd = pty.fork()
    if pid==0: os.execvpe('/bin/sh',['sh','-c',cmd],e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',rows,cols,0,0))
    out=b''; t0=time.time()
    def drain():
        nonlocal out
        while True:
            r,_,_=select.select([fd],[],[],0.03)
            if not r: return
            try: d=os.read(fd,65536)
            except OSError: return
            if not d: return
            out+=d
    drain()
    for k in keys:
        os.write(fd, k if isinstance(k,bytes) else k.encode('latin-1'))
        time.sleep(delay); drain()
    end=time.time()+timeout
    while time.time()<end: drain()
    try: os.kill(pid, signal.SIGKILL)
    except: pass
    try: os.waitpid(pid,0)
    except: pass
    return out
def run(args, keys=(), buf='/tmp/b3.txt', cols=80, rows=24, delay=0.35, timeout=2.0, bin=None, redirect=None):
    a=' '.join("'%s'"%x for x in args)
    r = (' < '+redirect) if redirect else (' < '+buf)
    cmd=(bin or BIN)+' '+a+r
    return ptyrun(cmd, K.parse('|'.join(keys)), cols, rows, delay, timeout)
def screen(args, keys=(), **kw):
    d=run(args, keys, **kw).decode('utf-8','replace')
    return ansi.styled(d, kw.get('cols',80), kw.get('rows',24))
def text(args, keys=(), **kw):
    d=run(args, keys, **kw).decode('utf-8','replace')
    return ansi.render(d, kw.get('cols',80), kw.get('rows',24))
def after(args, keys=(), **kw):
    d=run(args, keys, **kw).decode('utf-8','replace')
    i=d.rfind('\x1b[?1049l')
    return d[i+8:] if i>=0 else d
