cat >> peco/session.go <<'EOF'

// runCustomFilter feeds the buffer to an external filter process and maps the
// lines it prints back onto the buffer.
func (s *Session) runCustomFilter(name, query string, lines []*Line) []*Match {
	cf, ok := s.custom[name]
	if !ok || cf.cfg.Cmd == "" {
		return nil
	}
	args := []string{}
	seen := false
	for _, a := range cf.cfg.Args {
		if a == "$QUERY" {
			args = append(args, query)
			seen = true
			continue
		}
		args = append(args, a)
	}
	if !seen && len(cf.cfg.Args) == 0 {
		args = append(args, query)
	}
	cmd := exec.Command(cf.cfg.Cmd, args...)
	cmd.Stderr = os.Stderr
	in, err := cmd.StdinPipe()
	if err != nil {
		return nil
	}
	out, err := cmd.StdoutPipe()
	if err != nil {
		return nil
	}
	if err := cmd.Start(); err != nil {
		return nil
	}
	go func() {
		w := bufio.NewWriter(in)
		for _, l := range lines {
			w.WriteString(l.Raw)
			w.WriteByte('\n')
		}
		w.Flush()
		in.Close()
	}()
	sc := bufio.NewScanner(out)
	sc.Buffer(make([]byte, 64*1024), 8*1024*1024)
	matched := map[*Line]bool{}
	for sc.Scan() {
		t := sc.Text()
		for _, l := range lines {
			if l.Raw == t || l.Display == t {
				matched[l] = true
				break
			}
		}
	}
	cmd.Wait()
	var outMatches []*Match
	for _, l := range lines {
		if matched[l] {
			outMatches = append(outMatches, &Match{Line: l})
		}
	}
	return outMatches
}
EOF
