// sgrMerge folds a new SGR parameter list into the running attribute string.
func sgrMerge(old, params string) string {
	if params == "" || params == "0" {
		return ""
	}
	if old == "" {
		return params
	}
	// a reset in the middle starts a fresh list
	if strings.HasPrefix(params, "0;") || strings.HasPrefix(params, "0;") {
		return params
	}
	return old + ";" + params
}

// styleFromSGR turns an SGR attribute string into a tcell style.
func styleFromSGR(s string) tcell.Style {
	st := tcell.StyleDefault
	params := strings.Split(s, ";")
	for i := 0; i < len(params); i++ {
		p := params[i]
		n := atoiSafe(p)
		switch {
