			continue
		case n == 0:
			st = tcell.StyleDefault
		case n >= 30 && n <= 37:
			st = st.Foreground(tcell.ColorBlack + tcell.Color(n-30))
		case n == 39:
			st = st.Foreground(tcell.ColorDefault)
		case n >= 40 && n <= 47:
			st = st.Background(tcell.ColorBlack + tcell.Color(n-40))
		case n == 49:
