				c := tcell.NewRGBColor(int32(atoiSafe(params[i+2])), int32(atoiSafe(params[i+3])), int32(atoiSafe(params[i+4])))
				if n == 38 {
					st = st.Foreground(c)
				} else {
					st = st.Background(c)
				}
				i += 4
			}
		}
	}
