// parseSGR decodes an SGR parameter list into colors and attributes.
func parseSGR(s string) sgrStyle {
	out := sgrStyle{fg: config.ColorUnset, bg: config.ColorUnset}
	params := strings.Split(s, ";")
	for i := 0; i < len(params); i++ {
		n := atoiSafe(params[i])
		switch {
		case params[i] == "":
			continue
		case n == 0:
			out = sgrStyle{fg: config.ColorUnset, bg: config.ColorUnset}
		case n >= 30 && n <= 37:
			out.fgSet, out.fg = true, n-30
		case n == 39:
			out.fgSet, out.fg = true, config.ColorDefault
		case n >= 40 && n <= 47:
			out.bgSet, out.bg = true, n-40
		case n == 49:
			out.bgSet, out.bg = true, config.ColorDefault
		case n >= 90 && n <= 97:
			out.fgSet, out.fg = true, n-90+8
		case n >= 100 && n <= 107:
			out.bgSet, out.bg = true, n-100+8
		case n == 1:
			out.attrs |= config.AttrBold
		case n == 4:
			out.attrs |= config.AttrUnderline
		case n == 7:
			out.attrs |= config.AttrReverse
		case n == 22, n == 21:
			out.attrs &^= config.AttrBold
		case n == 24:
			out.attrs &^= config.AttrUnderline
		case n == 27:
			out.attrs &^= config.AttrReverse
		case n == 38, n == 48:
			if i+1 < len(params) && params[i+1] == "5" && i+2 < len(params) {
				v := atoiSafe(params[i+2])
				if v < 16 {
					v = 0x1000000 + v
				} else {
					v = 0x1000000 + v
				}
				if n == 38 {
					out.fgSet, out.fg = true, v
				} else {
					out.bgSet, out.bg = true, v
				}
				i += 2
			} else if i+1 < len(params) && params[i+1] == "2" && i+4 < len(params) {
				v := 0x1000000 | (atoiSafe(params[i+2]) << 16) | (atoiSafe(params[i+3]) << 8) | atoiSafe(params[i+4])
				if n == 38 {
					out.fgSet, out.fg = true, v
				} else {
					out.bgSet, out.bg = true, v
				}
				i += 4
			}
		}
	}
	return out
}
