// and the right hand status.
func (v *view) drawQuery(s *Session) {
	y := v.lay.queryRow
	width := v.cols
	right := fmt.Sprintf("%s [%d (%d/%d)]", s.currentFilterName(), s.count,
		s.page()+1, s.pageCount())
	rcol := width - stringWidth(right)
	if rcol < 0 {
		rcol = 0
		right = ""
	}
	for x := 0; x < width; x++ {
		v.setCell(x, y, ' ', v.st.querySt)
	}
	// prompt
	x := 0
	for _, g := range layout(s.prompt) {
		if x+g.width > rcol {
			break
		}
		v.putGrapheme(x, y, g, v.st.promptSt)
		x += g.width
	}
	// query text; the caret cell is styled with the QueryCursor style
	qg := layout(s.q.text)
	caret := s.q.caret
	textCol := x
	caretCol := -1
	for _, g := range qg {
		if g.runeLo == caret {
			caretCol = x
		}
		if x+g.width > rcol {
			break
		}
		st := v.st.querySt
		if g.runeLo == caret {
			st = v.st.queryCursorSt
		}
		v.putGrapheme(x, y, g, st)
		x += g.width
	}
	if caretCol < 0 {
		caretCol = x
		if x+1 <= rcol {
			v.setCell(x, y, ' ', v.st.queryCursorSt)
			x++
		}
	}
	// right hand side
	if rcol > 0 {
		cx := rcol
		for _, g := range layout(right) {
			if cx >= width {
				break
			}
			v.putGrapheme(cx, y, g, v.st.basicSt)
			cx += g.width
		}
	}
	v.setCursor(s, caretCol, y)
}

func (v *view) putGrapheme(x, y int, g grapheme, st tcell.Style) {
	v.scr.SetContent(x, y, firstRune(g.text), []rune(g.text[utf8.RuneLen(firstRune(g.text)):]), st)
}

