export GOTOOLCHAIN=go1.25.11 GOMODCACHE=/usr/local/go/mod-cache GOPROXY=off GOFLAGS=-mod=mod && gofmt -w peco/*.go && go vet ./peco/ 2>&1|head -6 && ./compile.sh && cd /tmp && python3 -c "
import sys,os,time,select,pty,fcntl,termios,struct,signal
sys.path.insert(0,'/tmp/h')
import ansi
for cols in [80,30]:
  for chars in [['日','本','語'],['a','b','c']]:
    pid,fd=pty.fork()
    if pid==0:
        os.environ['TERM']='xterm-256color'
        os.execv('/bin/sh',['sh','-c','/workspace/executable < /tmp/utf8.txt'])
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',6,cols,0,0))
    time.sleep(0.8); os.read(fd,65536)
    last=b''
    for ch in chars:
        os.write(fd, ch.encode()); time.sleep(0.35)
        while True:
            r,_,_=select.select([fd],[],[],0.05)
            if not r: break
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            last+=d
    os.kill(pid,signal.SIGKILL)
    d=last.decode('utf-8','replace')
    sc=ansi.run(d,cols,6)
    print('cols=%d q=%s' % (cols, ''.join(chars)), repr(''.join(c[0] for c in sc.cells[0])), 'cursor:', sc.cx+1)
""}

