// Locate looks for the configuration file in the standard locations and
// returns the first one that exists, or "" when there is none.
func Locate() string {
	var dirs []string
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		dirs = append(dirs, x)
	} else if home := os.Getenv("HOME"); home != "" {
		dirs = append(dirs, filepath.Join(home, ".config"))
	}
	if x := os.Getenv("XDG_CONFIG_DIRS"); x != "" {
		for _, d := range filepath.SplitList(x) {
			if d != "" {
				dirs = append(dirs, d)
			}
		}
	}
	if home := os.Getenv("HOME"); home != "" {
		dirs = append(dirs, filepath.Join(home, ".peco"))
	}
	for _, d := range dirs {
		for _, name := range []string{"config.json", "config.yaml", "config.yml"} {
			p := filepath.Join(d, "peco", name)
			if st, err := os.Stat(p); err == nil && !st.IsDir() {
				return p
			}
		}
	}
	return ""
}
