import ansi
def clean(o):
    o=o.replace(chr(27)+'[23;0;0t'+chr(27)+'[?1000l'+chr(27)+'[?1002l'+chr(27)+'[?1003l'+chr(27)+'[?1006l'+chr(27)+'[?2004l'+chr(27)+'[?1004l','')
    return o.strip().replace(chr(13)+chr(10),'|')
